    private void switchContentTab(
            LinearLayout targetLayout,
            android.view.View targetScroll,
            boolean home) {

        if (targetLayout != downloadsTabLayout) {
            restoreServerCardToRoot();
        }

        if (contentFrame == null ||
                targetLayout == null ||
                targetScroll == null) {
            return;
        }

        if (mainTabScroll != null) {
            mainTabScroll.setVisibility(
                    targetScroll == mainTabScroll
                            ? android.view.View.VISIBLE
                            : android.view.View.GONE
            );
        }

        if (spotifyTabScroll != null) {
            spotifyTabScroll.setVisibility(
                    targetScroll == spotifyTabScroll
                            ? android.view.View.VISIBLE
                            : android.view.View.GONE
            );
        }

        if (offlineTabContainer != null) {
            offlineTabContainer.setVisibility(
                    targetScroll == offlineTabContainer
                            ? android.view.View.VISIBLE
                            : android.view.View.GONE
            );
        }

        if (downloadsTabScroll != null) {
            downloadsTabScroll.setVisibility(
                    targetScroll == downloadsTabScroll
                            ? android.view.View.VISIBLE
                            : android.view.View.GONE
            );
        }

        if (favoritesTabScroll != null) {
            favoritesTabScroll.setVisibility(
                    targetScroll == favoritesTabScroll
                            ? android.view.View.VISIBLE
                            : android.view.View.GONE
            );
        }

        /*
         * MUY IMPORTANTE:
         *
         * contentLayout pasa a ser el contenedor de la
         * pestaña actualmente seleccionada.
         */
        contentLayout = targetLayout;

    // La tarjeta SERVIDOR solo debe ser visible dentro de DESCARGAS.
    if (serverCard != null) {
        serverCard.setVisibility(
                targetLayout == downloadsTabLayout
                        ? android.view.View.VISIBLE
                        : android.view.View.GONE
        );
    }


        if (home) {

            for (int i = 0;
                    i < rootLayout.getChildCount();
                    i++) {

                android.view.View child =
                        rootLayout.getChildAt(i);

                if (child == contentFrame ||
                        child == bottomNavigation) {
                    continue;
                }

                child.setVisibility(
                        android.view.View.VISIBLE
                );
            }

        } else {

            hideMainHome();
        }
    }

    private void restoreServerCardToRoot() {
        // La tarjeta SERVIDOR pertenece exclusivamente a DESCARGAS.
        // No se devuelve nunca al root principal.
    }

    private void showMainHome() {

        currentScreen = "music";

        if (rootLayout == null ||
                mainTabLayout == null ||
                mainTabScroll == null) {
            return;
        }

        switchContentTab(
                mainTabLayout,
                mainTabScroll,
                true
        );

        if (showingFavorites) {
            showingFavorites = false;

            if (searchCard != null) {
                searchCard.setVisibility(djResultsActive ? View.GONE : View.VISIBLE);
            }

            /*
             * Eliminamos las Views de Favoritos y devolvemos
             * exactamente las Views que tenía Música.
             */
            mainTabLayout.removeAllViews();

            for (android.view.View view :
                    savedMusicViews) {

                mainTabLayout.addView(view);
            }

            savedMusicViews.clear();

            /*
             * Recuperamos también la posición del scroll.
             */
            if (mainTabScroll != null) {

                mainTabScroll.post(() ->
                        mainTabScroll.scrollTo(
                                0,
                                savedMusicScrollY
                        )
                );
            }

            return;
        }

        if (searchCard != null) {
            searchCard.setVisibility(djResultsActive ? View.GONE : View.VISIBLE);
        }

        if (mainTabLayout.getChildCount() == 0 &&
                currentSearchSongs != null &&
                !currentSearchSongs.isEmpty()) {

            renderSearchSongsPage();
        }
    }

    private void hideMainHome() {

        if (rootLayout == null) {
            return;
        }

        for (int i = 0; i < rootLayout.getChildCount(); i++) {

            android.view.View child =
                    rootLayout.getChildAt(i);

            if (child == contentFrame ||
                    child == bottomNavigation) {
                continue;
            }

            child.setVisibility(
                    android.view.View.GONE
            );
        }
    }


    // COLA_ESTADO_VIVO_V1
    private android.app.AlertDialog activeQueueDialog;
    private android.widget.ScrollView activeQueueScroll;
    private LinearLayout activeQueueList;
    private TextView activeQueueTotal;
    private android.app.AlertDialog[] activeQueueDialogRef;
    private int queueScrollRestoreY = 0;

    private final Runnable queueLiveRefresh = () -> {
        if (activeQueueDialog == null ||
                !activeQueueDialog.isShowing()) {
            return;
        }

        if (activeQueueList != null && activeQueueDialogRef != null &&
                mediaController != null) {
            int previousY = activeQueueScroll == null ? 0 : activeQueueScroll.getScrollY();
            populateQueueDialogRows(activeQueueList, activeQueueDialogRef);
            if (activeQueueTotal != null) {
                activeQueueTotal.setText(mediaController.getMediaItemCount() + " canciones");
            }
            refreshQueueDialogProgress();
            if (activeQueueScroll != null) {
                activeQueueScroll.post(() -> {
                    if (activeQueueScroll != null) activeQueueScroll.scrollTo(0, previousY);
                });
            }
        }
    };

    private void scheduleQueueLiveRefresh() {
        handler.removeCallbacks(queueLiveRefresh);

        if (activeQueueDialog != null &&
                activeQueueDialog.isShowing()) {
            handler.postDelayed(queueLiveRefresh, 180);
        }
    }

    private void saveQueuePlaybackModes() {
        if (mediaController == null) return;

        getSharedPreferences(
                "queue_playback_modes_v1", MODE_PRIVATE
        ).edit()
         .putBoolean("saved", true)
         .putBoolean(
                 "shuffle",
                 mediaController.getShuffleModeEnabled()
         )
         .putInt(
                 "repeat",
                 mediaController.getRepeatMode()
         )
         .apply();
    }

    private void restoreQueuePlaybackModes() {
        if (mediaController == null) return;

        android.content.SharedPreferences prefs =
                getSharedPreferences(
                        "queue_playback_modes_v1",
                        MODE_PRIVATE
                );

        if (!prefs.getBoolean("saved", false)) {
            return;
        }

        boolean shuffle =
                prefs.getBoolean("shuffle", false);

        int repeat = prefs.getInt(
                "repeat",
                Player.REPEAT_MODE_OFF
        );

        if (mediaController.getShuffleModeEnabled()
                != shuffle) {
            mediaController.setShuffleModeEnabled(
                    shuffle
            );
        }

        if (mediaController.getRepeatMode()
                != repeat) {
            mediaController.setRepeatMode(repeat);
        }
    }

    private final Player.Listener playingCardListener =
            new Player.Listener() {

                @Override
                public void onTimelineChanged(
                        androidx.media3.common.Timeline timeline,
                        int reason) {

                    runOnUiThread(() -> {
                        restoreQueuePlaybackModes();
                        captureRecoverableQueue();
                        scheduleQueueLiveRefresh();
                    });
                }

                @Override
                public void onMediaItemTransition(
                        MediaItem mediaItem,
                        int reason
                ) {
                    runOnUiThread(
                            () -> {
                                updatePlayingCardStates();
                                scheduleQueueLiveRefresh();
                            }
                    );
                }

                @Override
                public void onIsPlayingChanged(
                        boolean isPlaying
                ) {
                    runOnUiThread(
                            () -> updatePlayingCardStates()
                    );
                }

                @Override
                public void onPlaybackStateChanged(
                        int playbackState
                ) {
                    runOnUiThread(
                            () -> updatePlayingCardStates()
                    );
                }
            };

    private void connectMediaController() {

        SessionToken token =
                new SessionToken(
                        this,
                        new ComponentName(
                                this,
                                PlayerService.class
                        )
                );

        MediaController.Builder builder =
                new MediaController.Builder(
                        this,
                        token
                );

        com.google.common.util.concurrent.ListenableFuture<MediaController>
                future =
                builder.buildAsync();

        future.addListener(
                () -> {

                    try {

                        mediaController =
                                future.get();

                        if (!mediaControllerListenerAttached) {

                            mediaController.addListener(
                                    playingCardListener
                            );

                            mediaControllerListenerAttached =
                                    true;
                        }

                        restoreQueuePlaybackModes();
                        updatePlayingCardStates();

                    } catch (Exception e) {

                        mediaController = null;
                    }

                },
                getMainExecutor()
        );
    }

    private void sendQueueToPlayer(
            List<MediaItem> items) {

        if (items == null ||
                items.isEmpty()) {

            Toast.makeText(
                    this,
                    "La cola está vacía",
                    Toast.LENGTH_SHORT
            ).show();

            return;
        }

        if (mediaController == null) {

            Toast.makeText(
                    this,
                    "Reproductor no conectado",
                    Toast.LENGTH_SHORT
            ).show();

            return;
        }

        QueueRepository.setQueue(items);

        SessionCommand command =
                new SessionCommand(
                        PlayerService.COMMAND_PLAY_QUEUE,
                        Bundle.EMPTY
                );

        mediaController.sendCustomCommand(
                command,
                Bundle.EMPTY
        );
    }


