private void loadFavoriteCover(
        JSONObject item,
        ImageView imageView
) {

    if (item == null ||
            imageView == null) {
        return;
    }

    String local =
            item.optString(
                    "thumbnailLocal",
                    ""
            ).trim();

    String remote =
            item.optString(
                    "thumbnail",
                    ""
            ).trim();

    String videoId =
            item.optString(
                    "videoId",
                    ""
            ).trim();

    String uriString =
            item.optString(
                    "uri",
                    ""
            ).trim();

    // FAVORITOS_PORTADAS_RESCATE_20261013
    // Recuperar ID de YouTube desde la clave cuando el campo videoId está vacío.
    if (!videoId.matches("[A-Za-z0-9_-]{11}")) {
        String key = item.optString("key", "").trim();
        String candidate = key.startsWith("song:") ? key.substring(5) : "";
        if (candidate.matches("[A-Za-z0-9_-]{11}")) videoId = candidate;
    }
    final String resolvedVideoId = videoId;

    artworkExecutor.execute(() -> {

        Bitmap bitmap = null;

        /*
         * 1. Intentar primero la portada local
         * guardada específicamente para Favoritos.
         */
        try {

            if (!local.isEmpty()) {

                java.io.File file =
                        new java.io.File(local);

                if (file.exists()) {

                    bitmap =
                            BitmapFactory.decodeFile(
                                    file.getAbsolutePath()
                            );
                }
            }

        } catch (Exception ignored) {
        }

        /*
         * 2. Intentar la portada remota guardada.
         */
        if (bitmap == null && !remote.isEmpty()) {
            try {
                Uri remoteUri = Uri.parse(remote);
                String scheme = remoteUri.getScheme();
                if ("content".equalsIgnoreCase(scheme) || "file".equalsIgnoreCase(scheme)) {
                    try (InputStream input = getContentResolver().openInputStream(remoteUri)) {
                        if (input != null) bitmap = BitmapFactory.decodeStream(input);
                    }
                } else if (scheme == null) {
                    java.io.File file = new java.io.File(remote);
                    if (file.isFile()) bitmap = BitmapFactory.decodeFile(file.getAbsolutePath());
                }
            } catch (Exception ignored) { }
        }

        if (bitmap == null &&
                !remote.isEmpty() &&
                (remote.startsWith("https://") || remote.startsWith("http://"))) {

            HttpURLConnection conn = null;

            try {

                conn =
                        (HttpURLConnection)
                                new URL(remote)
                                        .openConnection();

                conn.setConnectTimeout(8000);
                conn.setReadTimeout(10000);
                conn.setInstanceFollowRedirects(true);
                conn.setRequestProperty(
                        "User-Agent",
                        "Mozilla/5.0"
                );

                int responseCode =
                        conn.getResponseCode();

                if (responseCode >= 200 &&
                        responseCode < 300) {

                    try (InputStream input =
                                 conn.getInputStream()) {

                        bitmap =
                                BitmapFactory.decodeStream(
                                        input
                                );
                    }
                }

            } catch (Exception ignored) {

            } finally {

                if (conn != null) {
                    conn.disconnect();
                }
            }
        }

        /*
         * 3. Si todavía no hay portada,
         * utilizar directamente YouTube con el videoId.
         */
        if (bitmap == null &&
                !resolvedVideoId.isEmpty()) {

            HttpURLConnection conn = null;

            try {

                String youtubeUrl =
                        "https://i.ytimg.com/vi/"
                                + resolvedVideoId
                                + "/hqdefault.jpg";

                conn =
                        (HttpURLConnection)
                                new URL(youtubeUrl)
                                        .openConnection();

                conn.setConnectTimeout(8000);
                conn.setReadTimeout(10000);
                conn.setInstanceFollowRedirects(true);
                conn.setRequestProperty(
                        "User-Agent",
                        "Mozilla/5.0"
                );

                int responseCode =
                        conn.getResponseCode();

                if (responseCode >= 200 &&
                        responseCode < 300) {

                    try (InputStream input =
                                 conn.getInputStream()) {

                        bitmap =
                                BitmapFactory.decodeStream(
                                        input
                                );
                    }
                }

            } catch (Exception ignored) {

            } finally {

                if (conn != null) {
                    conn.disconnect();
                }
            }
        }

        /*
         * 4. Último recurso:
         * recuperar la portada incrustada en el
         * archivo offline.
         */
        if (bitmap == null &&
                !uriString.isEmpty()) {

            android.media.MediaMetadataRetriever retriever =
                    new android.media.MediaMetadataRetriever();

            try {

                Uri offlineUri =
                        Uri.parse(uriString);

                retriever.setDataSource(
                        MainActivity.this,
                        offlineUri
                );

                byte[] artwork =
                        retriever.getEmbeddedPicture();

                if (artwork != null &&
                        artwork.length > 0) {

                    bitmap =
                            BitmapFactory.decodeByteArray(
                                    artwork,
                                    0,
                                    artwork.length
                            );
                }

            } catch (Exception ignored) {

            } finally {

                try {
                    retriever.release();
                } catch (Exception ignored) {
                }
            }
        }

        /*
         * 5. Si hemos encontrado una portada,
         * guardarla como thumbnailLocal para que
         * el favorito no tenga que volver a descargarla.
         */
        if (bitmap != null) {

            try {

                java.io.File dir =
                        new java.io.File(
                                getFilesDir(),
                                "favorite_covers"
                        );

                if (!dir.exists()) {
                    dir.mkdirs();
                }

                String key =
                        item.optString(
                                "key",
                                "favorite"
                        );

                String safeKey =
                        key.replaceAll(
                                "[^a-zA-Z0-9._-]",
                                "_"
                        );

                java.io.File target =
                        new java.io.File(
                                dir,
                                safeKey + ".jpg"
                        );

                try (
                        java.io.FileOutputStream out =
                                new java.io.FileOutputStream(
                                        target
                                )
                ) {

                    bitmap.compress(
                            Bitmap.CompressFormat.JPEG,
                            90,
                            out
                    );

                    updateFavoriteThumbnailLocal(
                            key,
                            target.getAbsolutePath()
                    );
                }

            } catch (Exception ignored) {
            }
        }

        final Bitmap result = bitmap;

        handler.post(() -> {

            if (imageView.getParent() == null) return;
            if (result != null) {

                imageView.setImageBitmap(result);

            } else {

                imageView.setImageResource(android.R.drawable.ic_menu_gallery);
            }
        });
    });
}


private void updateFavoriteThumbnailLocal(
        String key,
        String localPath
) {

    if (key == null ||
            key.trim().isEmpty()) {
        return;
    }

    JSONArray favorites =
            getFavoritesArray();

    for (int i = 0;
            i < favorites.length();
            i++) {

        JSONObject item =
                favorites.optJSONObject(i);

        if (item == null) {
            continue;
        }

        if (key.equals(
                item.optString(
                        "key",
                        ""
                )
        )) {

            try {

                item.put(
                        "thumbnailLocal",
                        localPath
                );

            } catch (Exception ignored) {
            }

            break;
        }
    }

    saveFavoritesArray(
            favorites
    );
}


private String getFavoriteAlbumThumbnail(
        String albumId
) {

    if (albumId == null ||
            albumId.trim().isEmpty()) {
        return "";
    }

    return
            "https://coverartarchive.org/release-group/"
                    + albumId.trim()
                    + "/front";
}


