    private JSONObject albumToJson(
            ApiClient.Album album,
            boolean includeTracks) {

        JSONObject result = new JSONObject();

        if (album == null) {
            return result;
        }

        try {
            result.put(
                    "id",
                    album.id == null ? "" : album.id
            );

            result.put(
                    "title",
                    album.title == null ? "" : album.title
            );

            result.put(
                    "artist",
                    album.artist == null ? "" : album.artist
            );

            result.put(
                    "date",
                    album.date == null ? "" : album.date
            );

            result.put(
                    "type",
                    album.type == null ? "" : album.type
            );

            if (includeTracks) {

                JSONArray tracks =
                        new JSONArray();

                if (album.tracks != null) {

                    for (ApiClient.Song song :
                            album.tracks) {

                        if (song == null) continue;

                        JSONObject item =
                                new JSONObject();

                        item.put(
                                "number",
                                song.number
                        );

                        item.put(
                                "id",
                                song.id == null
                                        ? ""
                                        : song.id
                        );

                        item.put(
                                "videoId",
                                song.videoId == null
                                        ? ""
                                        : song.videoId
                        );

                        item.put(
                                "title",
                                song.title == null
                                        ? ""
                                        : song.title
                        );

                        item.put(
                                "artist",
                                song.artist == null
                                        ? ""
                                        : song.artist
                        );

                        item.put(
                                "channel",
                                song.channel == null
                                        ? ""
                                        : song.channel
                        );

                        item.put(
                                "album",
                                song.album == null
                                        ? ""
                                        : song.album
                        );

                        item.put(
                                "thumbnail",
                                song.thumbnail == null
                                        ? ""
                                        : song.thumbnail
                        );

                        item.put(
                                "duration",
                                song.duration
                        );

                        tracks.put(item);
                    }
                }

                result.put(
                        "tracks",
                        tracks
                );
            }

        } catch (Exception ignored) {
        }

        return result;
    }

    private ApiClient.Album albumFromJson(
            JSONObject json,
            boolean includeTracks) {

        if (json == null) {
            return null;
        }

        ApiClient.Album album =
                new ApiClient.Album();

        album.id =
                json.optString("id", "");

        album.title =
                json.optString("title", "");

        album.artist =
                json.optString("artist", "");

        album.date =
                json.optString("date", "");

        album.type =
                json.optString("type", "");

        if (includeTracks) {

            JSONArray tracks =
                    json.optJSONArray("tracks");

            if (tracks != null) {

                for (int i = 0;
                        i < tracks.length();
                        i++) {

                    JSONObject item =
                            tracks.optJSONObject(i);

                    if (item == null) continue;

                    ApiClient.Song song =
                            new ApiClient.Song();

                    song.number =
                            item.optInt(
                                    "number",
                                    0
                            );

                    song.id =
                            item.optString(
                                    "id",
                                    ""
                            );

                    song.videoId =
                            item.optString(
                                    "videoId",
                                    ""
                            );

                    song.title =
                            item.optString(
                                    "title",
                                    ""
                            );

                    song.artist =
                            item.optString(
                                    "artist",
                                    ""
                            );

                    song.channel =
                            item.optString(
                                    "channel",
                                    ""
                            );

                    song.album =
                            item.optString(
                                    "album",
                                    ""
                            );

                    song.thumbnail =
                            item.optString(
                                    "thumbnail",
                                    ""
                            );

                    song.duration =
                            item.optInt(
                                    "duration",
                                    0
                            );

                    album.tracks.add(song);
                }
            }
        }

        return album;
    }

    private void searchAlbums() {

        djGeneration++;
        djSearching = false;
        djStopAnimation();
        djResultsActive = false;
        if (searchCard != null) searchCard.setVisibility(View.VISIBLE);
        String query =
                searchInput
                        .getText()
                        .toString()
                        .trim();

        if (query.isEmpty()) return;

        saveSmartSearchHistory(query);
        dismissSmartSuggestions();

        // Recomendaciones fotográficas también en Álbumes.
        requestRelatedArtists(query, true);

        contentLayout.removeAllViews();

        LinearLayout loading =
                createSearchLoading(
                        "Buscando álbumes"
                );

        contentLayout.addView(loading);

        executor.execute(() -> {

            try {

                List<ApiClient.Album> albums =
                        api().searchAlbums(query);

                handler.post(
                        () -> showAlbums(albums)
                );

            } catch (Exception e) {

                handler.post(
                        () -> showError(e)
                );
            }
        });
    }

