    private void resolveAndPlayAlbumTrack(
            ApiClient.Song track,
            String albumId) {

        Toast.makeText(
                this,
                "Buscando audio: "
                        + track.title,
                Toast.LENGTH_SHORT
        ).show();

        executor.execute(() -> {

            try {

                SpotifyResolvedTrack resolvedResult =
                        resolveSpotifyTrackWithRetry(
                                track.artist,
                                track.title
                        );

                ApiClient.Song resolved =
                        resolvedResult.resolved;

                String url =
                        resolvedResult.url;

                String thumbnail =
                        track.thumbnail;

                if (
                        thumbnail == null ||
                        thumbnail.trim().isEmpty()
                ) {
                    thumbnail =
                            resolved.thumbnail;
                }

                if (
                        (thumbnail == null ||
                                thumbnail.trim().isEmpty()) &&
                        albumId != null &&
                        !albumId.trim().isEmpty()
                ) {
                    thumbnail =
                            "https://coverartarchive.org/release-group/"
                                    + albumId
                                    + "/front";
                }

                final String finalThumbnail =
                        thumbnail;

                handler.post(
                        () -> playResolved(
                                resolved.id,
                                url,
                                resolved.title,
                                finalThumbnail
                        )
                );

            } catch (Exception e) {

                handler.post(
                        () -> showError(e)
                );
            }
        });
    }

    private void playResolved(
            String url,
            String title) {

        playResolved(
                "",
                url,
                title,
                ""
        );
    }

    private void playResolved(
            String videoId,
            String url,
            String title,
            String thumbnail) {

        if (mediaController == null) {

            Toast.makeText(
                    this,
                    "Reproductor no conectado",
                    Toast.LENGTH_SHORT
            ).show();

            return;
        }

        MediaMetadata.Builder metadata =
                new MediaMetadata.Builder()
                        .setTitle(title);

        if (thumbnail != null &&
                !thumbnail.trim().isEmpty()) {
            metadata.setArtworkUri(
                    Uri.parse(thumbnail)
            );
        }

        MediaItem item =
                new MediaItem.Builder()
                        .setMediaId(
                                videoId == null ? "" : videoId
                        )
                        .setUri(url)
                        .setMediaMetadata(
                                metadata.build()
                        )
                        .build();

        mediaController.setMediaItem(item);
        mediaController.prepare();
        mediaController.play();
    }

    private static class AlbumResolvedTrack {
        final ApiClient.Song resolved;
        final String url;

        AlbumResolvedTrack(
                ApiClient.Song resolved,
                String url) {
            this.resolved = resolved;
            this.url = url;
        }
    }

    private AlbumResolvedTrack resolveAlbumTrackWithRetry(
            String artist,
            String title) throws Exception {

        return resolveAlbumTrackWithRetry(
                artist,
                title,
                "",
                ""
        );
    }

    private AlbumResolvedTrack resolveAlbumTrackWithRetry(
            String artist,
            String title,
            String albumTitle,
            String albumType) throws Exception {

        final long retryDeadline =
                System.currentTimeMillis() + 60000L;

        Exception lastError = null;

        while (System.currentTimeMillis() < retryDeadline) {

            try {

                ApiClient.Song resolved =
                        api().resolveAlbumTrack(
                                artist,
                                title,
                                albumTitle,
                                albumType
                        );

                if (resolved == null ||
                        resolved.id == null ||
                        resolved.id.trim().isEmpty()) {
                    throw new Exception(
                            "No se pudo obtener videoId"
                    );
                }

                String url =
                        api().getAudioUrl(
                                resolved.id
                        );

                if (url == null ||
                        url.trim().isEmpty()) {
                    throw new Exception(
                            "No se obtuvo URL de reproducción"
                    );
                }

                return new AlbumResolvedTrack(
                        resolved,
                        url
                );

            } catch (Exception error) {

                lastError = error;

                try {
                    Thread.sleep(3000L);
                } catch (InterruptedException interrupted) {
                    Thread.currentThread().interrupt();
                    throw interrupted;
                }
            }
        }

        if (lastError != null) {
            throw lastError;
        }

        throw new Exception(
                "Tiempo agotado esperando conexión"
        );
    }

    private void markAlbumTrackObtainedIndividual(
            long generation,
            int trackIndex) {

        handler.post(() -> {

            if (!isCurrentIndividualPlayback(
                    generation)) {
                return;
            }

            if (
                    trackIndex < 0 ||
                    trackIndex >=
                            albumPreparationStatusViews.size()
            ) {
                return;
            }

            TextView status =
                    albumPreparationStatusViews.get(
                            trackIndex
                    );

            if (status != null) {
                status.setText("✓ OBTENIDA");
                status.setTextColor(
                        Color.rgb(80, 220, 130)
                );
                status.setVisibility(
                        android.view.View.VISIBLE
                );
            }
        });
    }

    private void playAlbumFromIndex(
            ApiClient.Album album,
            int startIndex) {

        if (album == null ||
                album.tracks == null ||
                album.tracks.isEmpty() ||
                startIndex < 0 ||
                startIndex >= album.tracks.size()) {
            return;
        }

        final long playbackGeneration =
                beginIndividualPlayback();

        final int preparationTotal =
                album.tracks.size() - startIndex;

        final long queueGeneration =
                beginQueuePreparation(
                        preparationTotal
                );

        Toast.makeText(
                this,
                "Preparando desde la pista "
                        + (startIndex + 1)
                        + "...",
                Toast.LENGTH_SHORT
        ).show();

        executor.execute(() -> {

            try {
                ApiClient.Song firstTrack =
                        album.tracks.get(startIndex);

                AlbumResolvedTrack firstResolvedResult =
                        resolveAlbumTrackWithRetry(
                                firstTrack.artist,
                                firstTrack.title,
                                firstTrack.album,
                                firstTrack.albumType
                        );

                ApiClient.Song firstResolved =
                        firstResolvedResult.resolved;

                String firstUrl =
                        firstResolvedResult.url;

                markAlbumTrackObtainedIndividual(
                        playbackGeneration,
                        startIndex
                );

                updateQueuePreparationProgress(
                        queueGeneration,
                        1,
                        preparationTotal
                );

                String firstThumbnail =
                        firstTrack.thumbnail;

                if (firstThumbnail == null ||
                        firstThumbnail.trim().isEmpty()) {
                    firstThumbnail =
                            firstResolved.thumbnail;
                }

                if ((firstThumbnail == null ||
                        firstThumbnail.trim().isEmpty()) &&
                        album.id != null &&
                        !album.id.trim().isEmpty()) {

                    firstThumbnail =
                            "https://coverartarchive.org/release-group/"
                                    + album.id
                                    + "/front";
                }

                MediaMetadata.Builder firstMetadata =
                        new MediaMetadata.Builder()
                                .setTitle(firstTrack.title)
                                .setArtist(firstTrack.artist)
                                .setAlbumTitle(album.title);

                if (firstThumbnail != null &&
                        !firstThumbnail.trim().isEmpty()) {

                    firstMetadata.setArtworkUri(
                            Uri.parse(firstThumbnail)
                    );
                }

                MediaItem firstItem =
                        new MediaItem.Builder()
                                .setUri(firstUrl)
                                .setMediaMetadata(
                                        firstMetadata.setExtras(queueDurationExtras(firstTrack.duration)).build()
                                )
                                .build();

                List<MediaItem> firstList =
                        new ArrayList<>();

                firstList.add(firstItem);

                handler.post(() -> {

                    if (!isCurrentIndividualPlayback(
                            playbackGeneration)) {
                        return;
                    }

                    sendQueueToPlayer(firstList);
                });

                if (startIndex + 1 >= album.tracks.size()) {
                    return;
                }

                int remaining =
                        album.tracks.size()
                                - startIndex
                                - 1;

                int threads =
                        Math.min(
                                3,
                                Math.max(2, remaining)
                        );

                ExecutorService resolver =
                        Executors.newFixedThreadPool(
                                threads
                        );

                java.util.concurrent.ExecutorCompletionService<
                        java.util.AbstractMap.SimpleEntry<
                                Integer,
                                MediaItem
                        >
                > completionService =
                        new java.util.concurrent.ExecutorCompletionService<>(
                                resolver
                        );

                int submitted = 0;

                java.util.concurrent.atomic.AtomicInteger preparationLoaded =
                        new java.util.concurrent.atomic.AtomicInteger(1);

                for (
                        int index = startIndex + 1;
                        index < album.tracks.size();
                        index++
                ) {

                    final int trackIndex = index;

                    completionService.submit(() -> {

                        ApiClient.Song track =
                                album.tracks.get(trackIndex);

                        AlbumResolvedTrack resolvedResult =
                                resolveAlbumTrackWithRetry(
                                        track.artist,
                                        track.title,
                                        track.album,
                                        track.albumType
                                );

                        ApiClient.Song resolved =
                                resolvedResult.resolved;

                        String url =
                                resolvedResult.url;

                        markAlbumTrackObtainedIndividual(
                                playbackGeneration,
                                trackIndex
                        );

                        updateQueuePreparationProgress(
                                queueGeneration,
                                preparationLoaded.incrementAndGet(),
                                preparationTotal
                        );

                        String thumbnail =
                                track.thumbnail;

                        if (thumbnail == null ||
                                thumbnail.trim().isEmpty()) {
                            thumbnail =
                                    resolved.thumbnail;
                        }

                        if ((thumbnail == null ||
                                thumbnail.trim().isEmpty()) &&
                                album.id != null &&
                                !album.id.trim().isEmpty()) {

                            thumbnail =
                                    "https://coverartarchive.org/release-group/"
                                            + album.id
                                            + "/front";
                        }

                        MediaMetadata.Builder metadata =
                                new MediaMetadata.Builder()
                                        .setTitle(track.title)
                                        .setArtist(track.artist)
                                        .setAlbumTitle(album.title);

                        if (thumbnail != null &&
                                !thumbnail.trim().isEmpty()) {

                            metadata.setArtworkUri(
                                    Uri.parse(thumbnail)
                            );
                        }

                        MediaItem item =
                                new MediaItem.Builder()
                                        .setUri(url)
                                        .setMediaMetadata(
                                                metadata.setExtras(queueDurationExtras(track.duration)).build()
                                        )
                                        .build();

                        return new java.util.AbstractMap.SimpleEntry<>(
                                trackIndex,
                                item
                        );
                    });

                    submitted++;
                }

                Map<Integer, MediaItem> ready =
                        new java.util.HashMap<>();

                int nextIndex = startIndex + 1;

                for (int i = 0; i < submitted; i++) {

                    java.util.concurrent.Future<
                            java.util.AbstractMap.SimpleEntry<
                                    Integer,
                                    MediaItem
                            >
                    > future =
                            completionService.take();

                    java.util.AbstractMap.SimpleEntry<
                            Integer,
                            MediaItem
                    > result =
                            future.get();

                    if (result == null) {
                        continue;
                    }

                    ready.put(
                            result.getKey(),
                            result.getValue()
                    );

                    while (ready.containsKey(nextIndex)) {

                        MediaItem item =
                                ready.remove(nextIndex);

                        List<MediaItem> next =
                                new ArrayList<>();

                        next.add(item);

                        final List<MediaItem> itemsToAdd =
                                next;

                        handler.post(() -> {

                            if (!isCurrentIndividualPlayback(
                                    playbackGeneration)) {
                                return;
                            }

                            addItemsToPlayerQueue(
                                    itemsToAdd
                            );
                        });

                        nextIndex++;
                    }
                }

                resolver.shutdown();

            } catch (Exception error) {

                Log.e(
                        "MUSIC_DOWNLOAD",
                        "Error preparando álbum",
                        error
                );
            }
        });
    }

    private void playAlbum(
            ApiClient.Album album) {


        final int albumTotal =
                album != null &&
                album.tracks != null
                        ? album.tracks.size()
                        : 0;

        final long playbackGeneration =
                beginIndividualPlayback();

        final long queueGeneration =
                beginQueuePreparation(
                        albumTotal
                );

Toast.makeText(
                this,
                "Preparando álbum completo...",
                Toast.LENGTH_LONG
        ).show();

        executor.execute(() -> {

            List<MediaItem> items =
                    new ArrayList<>();

            int failed = 0;
            int preparationTrackIndex = 0;

            for (
                    ApiClient.Song track :
                    album.tracks
            ) {

                final int currentPreparationTrackIndex =
                        preparationTrackIndex++;

                try {

                    AlbumResolvedTrack resolvedResult =
                            resolveAlbumTrackWithRetry(
                                    track.artist,
                                    track.title,
                                    track.album,
                                    track.albumType
                            );

                    ApiClient.Song resolved =
                            resolvedResult.resolved;

                    String url =
                            resolvedResult.url;

                    String thumbnail =
                            track.thumbnail;

                    if (
                            thumbnail == null ||
                            thumbnail.trim().isEmpty()
                    ) {
                        thumbnail =
                                resolved.thumbnail;
                    }

                    if (
                            (thumbnail == null ||
                                    thumbnail.trim().isEmpty()) &&
                            album.id != null &&
                            !album.id.trim().isEmpty()
                    ) {
                        thumbnail =
                                "https://coverartarchive.org/release-group/"
                                        + album.id
                                        + "/front";
                    }

                    MediaMetadata.Builder metadata =
                            new MediaMetadata.Builder()
                                    .setTitle(
                                            track.title
                                    )
                                    .setArtist(
                                            track.artist
                                    )
                                    .setAlbumTitle(
                                            album.title
                                    );

                    if (
                            thumbnail != null &&
                            !thumbnail.trim().isEmpty()
                    ) {
                        metadata.setArtworkUri(
                                Uri.parse(thumbnail)
                        );
                    }

                    MediaItem item =
                            new MediaItem.Builder()
                                    .setUri(url)
                                    .setMediaMetadata(
                                            metadata.setExtras(queueDurationExtras(track.duration)).build()
                                    )
                                    .build();

                    items.add(item);

                    updateQueuePreparationProgress(
                            queueGeneration,
                            items.size(),
                            albumTotal
                    );

                    markAlbumTrackObtained(
                            queueGeneration,
                            currentPreparationTrackIndex
                    );

                    /*
                     * La primera canción comienza inmediatamente.
                     * Las siguientes se añaden progresivamente.
                     */
                    if (items.size() == 1) {

                        final MediaItem firstItem = item;

                        handler.post(() -> {

                            if (!isCurrentIndividualPlayback(
                                    playbackGeneration)) {
                                return;
                            }

                            List<MediaItem> first =
                                    new ArrayList<>();

                            first.add(firstItem);

                            sendQueueToPlayer(first);
                        });

                    } else {

                        List<MediaItem> next =
                                new ArrayList<>();

                        next.add(item);

                        handler.post(() -> {

                            if (!isCurrentIndividualPlayback(
                                    playbackGeneration)) {
                                return;
                            }

                            addItemsToPlayerQueue(next);
                        });
                    }

                } catch (Exception trackError) {

                    failed++;

                    // Se salta esta pista y continúa con el álbum.
                }
            }

            final int totalPrepared = items.size();
            final int totalFailed = failed;

            handler.post(() -> {

                if (
                        mediaController == null
                ) {

                    Toast.makeText(
                            this,
                            "Reproductor no conectado",
                            Toast.LENGTH_SHORT
                    ).show();

                    return;
                }

                if (
                        items.isEmpty()
                ) {

                    Toast.makeText(
                            this,
                            "No se pudo preparar ninguna canción del álbum",
                            Toast.LENGTH_LONG
                    ).show();

                    return;
                }

                String message;

                if (
                        totalFailed > 0
                ) {

                    message =
                            "Álbum: "
                                    + totalPrepared
                                    + " canciones"
                                    + " ("
                                    + totalFailed
                                    + " no disponibles)";

                } else {

                    message =
                            "Álbum preparado: "
                                    + totalPrepared
                                    + " canciones";
                }

                Toast.makeText(
                        this,
                        message,
                        Toast.LENGTH_LONG
                ).show();
            });
        });
    }

