    // Acciones visuales de canción; no cambia operaciones ni orden de la lista.
    private void personalEditOneTrack(String id, int index) {
        JSONObject list = PersonalPlaylists.get(this, id);
        if (list == null) return;
        JSONArray tracks = list.optJSONArray("tracks");
        JSONObject track = tracks == null ? null : tracks.optJSONObject(index);
        if (track == null) return;
        LinearLayout panel = personalUiPanel();
        LinearLayout header = personalUiHeader("♫", track.optString("title", "Canción"),
                track.optString("artist", "Artista desconocido") + " · " + (index + 1));
        panel.addView(header, (LinearLayout.LayoutParams) header.getTag());
        final AlertDialog[] dialog = new AlertDialog[1];
        personalAddUiCard(panel, personalUiAction("↑", "Subir canción",
                "Mover una posición hacia arriba", Color.rgb(178, 157, 255), v -> {
                    dialog[0].dismiss();
                    try { PersonalPlaylists.moveTrack(this, id, index, -1); }
                    catch (Exception e) { Toast.makeText(this, e.getMessage(), Toast.LENGTH_LONG).show(); }
                    personalEditTracks(id);
                }));
        personalAddUiCard(panel, personalUiAction("↓", "Bajar canción",
                "Mover una posición hacia abajo", Color.rgb(178, 157, 255), v -> {
                    dialog[0].dismiss();
                    try { PersonalPlaylists.moveTrack(this, id, index, 1); }
                    catch (Exception e) { Toast.makeText(this, e.getMessage(), Toast.LENGTH_LONG).show(); }
                    personalEditTracks(id);
                }));
        personalAddUiCard(panel, personalUiAction("×", "Quitar de la lista",
                "No se borra el archivo de audio", Color.rgb(255, 135, 151), v -> {
                    dialog[0].dismiss();
                    new AlertDialog.Builder(this).setTitle("Quitar canción")
                            .setMessage("¿Quitar esta canción de la lista? No se borrará el audio.")
                            .setNegativeButton("Cancelar", (d, w) -> personalEditTracks(id))
                            .setPositiveButton("Quitar", (d, w) -> {
                                try { PersonalPlaylists.removeTrack(this, id, index); }
                                catch (Exception e) { Toast.makeText(this, e.getMessage(), Toast.LENGTH_LONG).show(); }
                                personalEditTracks(id);
                            }).show();
                }));
        ScrollView scroll = new ScrollView(this);
        scroll.addView(panel);
        dialog[0] = new AlertDialog.Builder(this).setView(scroll)
                .setNegativeButton("Volver", (d, w) -> personalEditTracks(id)).create();
        dialog[0].show();
    }


    private JSONObject personalSong(String title,String artist,String album,int duration,String uri) {
        JSONObject song=new JSONObject();
        try {
            song.put("title",title==null?"":title.trim());
            song.put("artist",artist==null?"":artist.trim());
            song.put("album",album==null?"":album.trim());
            song.put("duration",Math.max(0,duration));
            song.put("uri",uri==null?"":uri);
        } catch(Exception ignored) { }
        return song;
    }

    private JSONObject personalFromSong(ApiClient.Song song) {
        String artist= song.artist==null || song.artist.trim().isEmpty()?song.channel:song.artist;
        JSONObject item = personalSong(song.title,artist,song.album,song.duration,"");
        try { item.put("thumbnail", song.thumbnail); item.put("videoId", song.videoId); }
        catch (Exception ignored) { }
        return item;
    }

    private JSONObject personalFromSpotify(ApiClient.SpotifyTrack track) {
        JSONObject item = personalSong(track.title,track.artist,track.album,track.duration,"");
        try { item.put("thumbnail", track.thumbnail); }
        catch (Exception ignored) { }
        return item;
    }

    private void personalChooseListForSongs(JSONArray songs) {
        if(songs.length()==0) {
            Toast.makeText(this,"No hay canciones seleccionadas",Toast.LENGTH_SHORT).show(); return;
        }
        JSONArray all=PersonalPlaylists.load(this);
        String[] names=new String[all.length()+1];
        for(int i=0;i<all.length();i++) names[i]=all.optJSONObject(i).optString("name");
        names[all.length()]="➕ Crear nueva lista";
        new AlertDialog.Builder(this).setTitle("Añadir "+songs.length()+" canciones a...")
            .setItems(names,(d,which)->{
                if(which==all.length()) {
                    EditText input=new EditText(this);
                    input.setHint("Nombre de la lista");
                    new AlertDialog.Builder(this).setTitle("Nueva lista")
                        .setView(input).setNegativeButton("Cancelar",null)
                        .setPositiveButton("Crear y añadir",(d2,w)->{
                            try {
                                String id=PersonalPlaylists.create(this,input.getText().toString());
                                PersonalPlaylists.add(this,id,songs);
                                Toast.makeText(this,"Canciones añadidas",Toast.LENGTH_SHORT).show();
                            } catch(Exception e) { Toast.makeText(this,e.getMessage(),Toast.LENGTH_LONG).show(); }
                        }).show();
                    return;
                }
                try {
                    PersonalPlaylists.add(this,all.getJSONObject(which).optString("id"),songs);
                    Toast.makeText(this,"Canciones añadidas",Toast.LENGTH_SHORT).show();
                } catch(Exception e) { Toast.makeText(this,e.getMessage(),Toast.LENGTH_LONG).show(); }
            }).setNegativeButton("Cancelar",null).show();
    }

    private void personalAddSong(ApiClient.Song song) {
        JSONArray songs=new JSONArray(); songs.put(personalFromSong(song)); personalChooseListForSongs(songs);
    }
    private void personalAddSpotifyTrack(ApiClient.SpotifyTrack track) {
        JSONArray songs=new JSONArray(); songs.put(personalFromSpotify(track)); personalChooseListForSongs(songs);
    }
    private void personalAddAlbum(ApiClient.Album album) {
        JSONArray songs=new JSONArray();
        for(ApiClient.Song track:album.tracks) {
            JSONObject item = personalSong(track.title,
                track.artist==null || track.artist.isEmpty()?album.artist:track.artist,
                album.title,track.duration,"");
            try { item.put("thumbnail", track.thumbnail); item.put("videoId", track.videoId); }
            catch(Exception ignored) { }
            songs.put(item);
        }
        personalChooseListForSongs(songs);
    }
    private void personalAddSelectedSpotify() {
        JSONArray songs=new JSONArray();
        for(int i=0;i<spotifySelectionChecks.size() && i<spotifySelectionTracks.size();i++)
            if(spotifySelectionChecks.get(i).isChecked())
                songs.put(personalFromSpotify(spotifySelectionTracks.get(i)));
        personalChooseListForSongs(songs);
    }
    // FIX_FAVORITOS_LISTAS_ALBUM_DURACION_V1
    // Los Favoritos de álbum almacenan albumId, no necesariamente tracks.
    // Los Favoritos de canción suelen guardar duración en milisegundos;
    // PersonalPlaylists espera segundos.
    private int personalFavoriteSeconds(long value) {
        if (value <= 0L) return 0;
        // Los tiempos normales de Favoritos vienen como 251000 ms (4:11).
        // Las duraciones expresadas como segundos se conservan.
        long seconds = value >= 10000L ? value / 1000L : value;
        return (int) Math.min(Integer.MAX_VALUE, seconds);
    }

    private JSONObject personalFavoriteSong(JSONObject t) {
        JSONObject result = personalSong(
                t.optString("title"), t.optString("artist"),
                t.optString("album"), personalFavoriteSeconds(t.optLong("duration", 0L)),
                t.optString("uri", ""));
        try {
            result.put("thumbnail", t.optString("thumbnail", ""));
            result.put("thumbnailLocal", t.optString("thumbnailLocal", ""));
            result.put("videoId", t.optString("videoId", ""));
        } catch (Exception ignored) { }
        return result;
    }

    private void personalAddSelectedFavorites() {
        final JSONArray songs = new JSONArray();
        final java.util.ArrayList<JSONObject> albums = new java.util.ArrayList<>();
        // Recogemos selecciones en el hilo UI antes de cargar ningún álbum.
        for (CheckBox check : favoriteSelectionChecks) {
            if (!check.isChecked() || !(check.getTag() instanceof JSONObject)) continue;
            JSONObject item = (JSONObject) check.getTag();
            if ("album".equals(item.optString("type"))) {
                albums.add(item);
            } else {
                songs.put(personalFavoriteSong(item));
            }
        }
        if (songs.length() == 0 && albums.isEmpty()) {
            Toast.makeText(this, "No hay canciones seleccionadas", Toast.LENGTH_SHORT).show();
            return;
        }
        if (albums.isEmpty()) {
            personalChooseListForSongs(songs);
            return;
        }
        Toast.makeText(this, "Cargando pistas de álbumes favoritos...", Toast.LENGTH_SHORT).show();
        executor.execute(() -> {
            final JSONArray complete = new JSONArray();
            // Mantener las canciones sueltas seleccionadas.
            for (int i = 0; i < songs.length(); i++) complete.put(songs.opt(i));
            int failed = 0;
            for (JSONObject favorite : albums) {
                String albumId = favorite.optString("albumId", "").trim();
                if (albumId.isEmpty()) { failed++; continue; }
                try {
                    ApiClient.Album album = getFavoriteAlbumWithRetry(albumId);
                    if (album == null || album.tracks == null || album.tracks.isEmpty()) {
                        failed++;
                        continue;
                    }
                    for (ApiClient.Song track : album.tracks) {
                        if (track == null || track.title == null || track.title.trim().isEmpty()) continue;
                        JSONObject song = personalFromSong(track);
                        try {
                            if (song.optString("artist").isEmpty())
                                song.put("artist", favorite.optString("artist"));
                            if (song.optString("album").isEmpty())
                                song.put("album", favorite.optString("title"));
                            if (song.optString("thumbnail").isEmpty())
                                song.put("thumbnail", favorite.optString("thumbnail"));
                        } catch (Exception ignored) { }
                        complete.put(song);
                    }
                } catch (Exception error) {
                    failed++;
                    android.util.Log.w("PersonalPlaylists", "No se pudo cargar álbum favorito " + albumId, error);
                }
            }
            final int failedAlbums = failed;
            handler.post(() -> {
                if (failedAlbums > 0) Toast.makeText(this,
                        failedAlbums + " álbum(es) no se pudieron cargar", Toast.LENGTH_LONG).show();
                personalChooseListForSongs(complete);
            });
        });
    }

