    private void playSpotifyPlaylistFromIndex(
            ApiClient.SpotifyPlaylist playlist,
            int startIndex) {
        final long playbackGeneration =
                beginIndividualPlayback();



        final int playlistTotal =
                playlist != null &&
                playlist.tracks != null
                        ? playlist.tracks.size()
                        : 0;

        final long queueGeneration =
                beginQueuePreparation(
                        playlistTotal
                );

if (playlist == null ||
                playlist.tracks == null ||
                playlist.tracks.isEmpty() ||
                startIndex < 0 ||
                startIndex >= playlist.tracks.size()) {

            return;
        }

        Toast.makeText(
                this,
                "Preparando desde la canción "
                        + (startIndex + 1)
                        + "...",
                Toast.LENGTH_SHORT
        ).show();

        executor.execute(() -> {

            try {

                final int total =
                        playlist.tracks.size();

                /*
                 * =========================================================
                 * 1. RESOLVER PRIMERO LA CANCIÓN SELECCIONADA
                 * =========================================================
                 */

                ApiClient.SpotifyTrack firstTrack =
                        playlist.tracks.get(startIndex);

                if (
                        firstTrack == null ||
                        firstTrack.artist == null ||
                        firstTrack.title == null ||
                        (
                                firstTrack.artist.trim().isEmpty() &&
                                firstTrack.title.trim().isEmpty()
                        )
                ) {

                    handler.post(() ->
                            Toast.makeText(
                                    this,
                                    "No se pudo resolver la canción",
                                    Toast.LENGTH_SHORT
                            ).show()
                    );

                    return;
                }

                ApiClient.Song firstResolved =
                        api().resolveAlbumTrack(
                                firstTrack.artist,
                                firstTrack.title
                        );

                if (
                        firstResolved == null ||
                        firstResolved.id == null ||
                        firstResolved.id.trim().isEmpty()
                ) {

                    handler.post(() ->
                            Toast.makeText(
                                    this,
                                    "No se encontró el audio",
                                    Toast.LENGTH_SHORT
                            ).show()
                    );

                    return;
                }

                String firstUrl =
                        api().getPreviewUrl(
                                firstResolved.id
                        );

                if (
                        firstUrl == null ||
                        firstUrl.trim().isEmpty()
                ) {

                    handler.post(() ->
                            Toast.makeText(
                                    this,
                                    "No se pudo obtener el audio",
                                    Toast.LENGTH_SHORT
                            ).show()
                    );

                    return;
                }

                MediaMetadata.Builder firstMetadata =
                        new MediaMetadata.Builder()
                                .setTitle(
                                        firstTrack.title
                                );

                if (
                        firstTrack.artist != null &&
                        !firstTrack.artist.trim().isEmpty()
                ) {

                    firstMetadata.setArtist(
                            firstTrack.artist
                    );
                }

                if (
                        firstTrack.album != null &&
                        !firstTrack.album.trim().isEmpty()
                ) {

                    firstMetadata.setAlbumTitle(
                            firstTrack.album
                    );
                }

                String firstThumbnail =
                        firstTrack.thumbnail;

                if (
                        (firstThumbnail == null ||
                                firstThumbnail.trim().isEmpty()) &&
                        firstResolved.thumbnail != null &&
                        !firstResolved.thumbnail.trim().isEmpty()
                ) {

                    firstThumbnail =
                            firstResolved.thumbnail;
                }

                if (
                        firstThumbnail != null &&
                        !firstThumbnail.trim().isEmpty()
                ) {

                    firstMetadata.setArtworkUri(
                            Uri.parse(firstThumbnail)
                    );
                }

                MediaItem firstItem =
                        new MediaItem.Builder()
                                .setUri(firstUrl)
                                .setMediaMetadata(
                                        firstMetadata.setExtras(queueDurationExtras(firstTrack.duration)).build()
                                )
                                .build();

                List<MediaItem> firstList =
                        new ArrayList<>();

                firstList.add(firstItem);

                /*
                 * =========================================================
                 * 2. ARRANCAR EXACTAMENTE COMO REPRODUCIR TODO
                 * =========================================================
                 */

                handler.post(() -> {
                    if (!isCurrentIndividualPlayback(
                            playbackGeneration)) {
                        return;
                    }

                    sendQueueToPlayer(firstList);

                    updateQueuePreparationProgress(
                            queueGeneration,
                            1,
                            playlistTotal
                    );

                    markSpotifyTrackObtained(
                            queueGeneration,
                            startIndex
                    );
                });

                /*
                 * =========================================================
                 * 3. RESOLVER EL RESTO DESDE startIndex + 1
                 *
                 * Usamos exactamente el mismo sistema que Spotify TODO:
                 * varios resolvers en paralelo + mapa por índice +
                 * incorporación estrictamente consecutiva.
                 * =========================================================
                 */

                if (startIndex >= total - 1) {

                    handler.post(() ->
                            Toast.makeText(
                                    this,
                                    "Spotify preparado: 1 canción",
                                    Toast.LENGTH_SHORT
                            ).show()
                    );

                    return;
                }

                /*
                 * =========================================================
                 * RESOLUCIÓN DE SPOTIFY EN TANDAS ESTRICTAS DE 3
                 *
                 * Nunca se meten todas las canciones pendientes en el
                 * executor de golpe.
                 *
                 * 1,2,3  -> esperar -> añadir
                 * 4,5,6  -> esperar -> añadir
                 * 7,8,9  -> esperar -> añadir
                 * ...
                 *
                 * Al terminar la primera pasada se vuelven a intentar
                 * exclusivamente las canciones que hayan fallado.
                 * =========================================================
                 */

                int addedCount = 1;

                java.util.Map<Integer, MediaItem>
                        resolvedSpotifyItems =
                        new java.util.HashMap<>();

                java.util.ArrayList<Integer> failedSpotifyIndexes =
                        new java.util.ArrayList<>();

                int batchStart =
                        startIndex + 1;

                while (batchStart < total) {

                    int batchEnd =
                            Math.min(
                                    batchStart + 3,
                                    total
                            );

                    int batchSize =
                            batchEnd - batchStart;

                    ExecutorService resolver =
                            Executors.newFixedThreadPool(
                                    batchSize
                            );

                    java.util.concurrent.ExecutorCompletionService<
                            java.util.AbstractMap.SimpleEntry<
                                    Integer,
                                    MediaItem
                            >
                            > completionService =
                            new java.util.concurrent.ExecutorCompletionService<>(
                                    resolver
                            );

                    for (
                            int index = batchStart;
                            index < batchEnd;
                            index++
                    ) {

                        final int trackIndex = index;

                        completionService.submit(() -> {

                            ApiClient.SpotifyTrack track =
                                    playlist.tracks.get(
                                            trackIndex
                                    );

                            try {

                                if (
                                        track == null ||
                                        track.artist == null ||
                                        track.title == null ||
                                        (
                                                track.artist.trim().isEmpty() &&
                                                track.title.trim().isEmpty()
                                        )
                                ) {

                                    return new java.util.AbstractMap.SimpleEntry<>(
                                            trackIndex,
                                            null
                                    );
                                }

                                SpotifyResolvedTrack resolvedResult =
                                        resolveSpotifyTrackWithRetry(
                                                track.artist,
                                                track.title
                                        );

                                ApiClient.Song resolved =
                                        resolvedResult.resolved;

                                String url =
                                        resolvedResult.url;

                                MediaMetadata.Builder metadata =
                                        new MediaMetadata.Builder()
                                                .setTitle(
                                                        track.title
                                                );

                                if (
                                        track.artist != null &&
                                        !track.artist.trim().isEmpty()
                                ) {

                                    metadata.setArtist(
                                            track.artist
                                    );
                                }

                                if (
                                        track.album != null &&
                                        !track.album.trim().isEmpty()
                                ) {

                                    metadata.setAlbumTitle(
                                            track.album
                                    );
                                }

                                String thumbnail =
                                        track.thumbnail;

                                if (
                                        (thumbnail == null ||
                                                thumbnail.trim().isEmpty()) &&
                                        resolved.thumbnail != null &&
                                        !resolved.thumbnail.trim().isEmpty()
                                ) {

                                    thumbnail =
                                            resolved.thumbnail;
                                }

                                if (
                                        thumbnail != null &&
                                        !thumbnail.trim().isEmpty()
                                ) {

                                    metadata.setArtworkUri(
                                            Uri.parse(thumbnail)
                                    );
                                }

                                MediaItem item =
                                        new MediaItem.Builder()
                                                .setUri(url)
                                                .setMediaMetadata(
                                                        metadata.setExtras(queueDurationExtras(track.duration)).build()
                                                )
                                                .build();

                                return new java.util.AbstractMap.SimpleEntry<>(
                                        trackIndex,
                                        item
                                );

                            } catch (Exception error) {

                                return new java.util.AbstractMap.SimpleEntry<>(
                                        trackIndex,
                                        null
                                );
                            }
                        });
                    }

                    resolver.shutdown();

                    java.util.Map<Integer, MediaItem> readyBatch =
                            new java.util.HashMap<>();

                    for (
                            int completed = 0;
                            completed < batchSize;
                            completed++
                    ) {

                        java.util.AbstractMap.SimpleEntry<
                                Integer,
                                MediaItem
                                > result =
                                completionService.take().get();

                        readyBatch.put(
                                result.getKey(),
                                result.getValue()
                        );
                    }

                    for (
                            int index = batchStart;
                            index < batchEnd;
                            index++
                    ) {

                        MediaItem item =
                                readyBatch.get(
                                        index
                                );

                        if (item == null) {

                            failedSpotifyIndexes.add(
                                    index
                            );

                            continue;
                        }

                        List<MediaItem> one =
                                new ArrayList<>();

                        one.add(item);

                        addedCount++;

                        resolvedSpotifyItems.put(
                                index,
                                item
                        );

                        final int preparedTrackIndex =
                                index;

                        updateQueuePreparationProgress(
                                queueGeneration,
                                addedCount,
                                playlistTotal
                        );

                        markSpotifyTrackObtained(
                                queueGeneration,
                                preparedTrackIndex
                        );

                        handler.post(() -> {

                            if (!isCurrentIndividualPlayback(
                                    playbackGeneration)) {
                                return;
                            }

                            addItemsToPlayerQueue(one);
                        });
                    }

                    batchStart =
                            batchEnd;
                }

                /*
                 * =========================================================
                 * REESCAN DE LAS QUE FALLARON
                 *
                 * Solo se vuelven a intentar las que no se pudieron
                 * resolver en la primera pasada.
                 *
                 * También aquí máximo 3 simultáneas.
                 * =========================================================
                 */

                if (!failedSpotifyIndexes.isEmpty()) {

                    java.util.ArrayList<Integer> secondPassFailed =
                            new java.util.ArrayList<>();

                    int failedStart = 0;

                    while (
                            failedStart <
                                    failedSpotifyIndexes.size()
                    ) {

                        int failedEnd =
                                Math.min(
                                        failedStart + 3,
                                        failedSpotifyIndexes.size()
                                );

                        int failedBatchSize =
                                failedEnd - failedStart;

                        ExecutorService retryResolver =
                                Executors.newFixedThreadPool(
                                        failedBatchSize
                                );

                        java.util.concurrent.ExecutorCompletionService<
                                java.util.AbstractMap.SimpleEntry<
                                        Integer,
                                        MediaItem
                                >
                                > retryCompletion =
                                new java.util.concurrent.ExecutorCompletionService<>(
                                        retryResolver
                                );

                        for (
                                int position = failedStart;
                                position < failedEnd;
                                position++
                        ) {

                            final int trackIndex =
                                    failedSpotifyIndexes.get(
                                            position
                                    );

                            retryCompletion.submit(() -> {

                                ApiClient.SpotifyTrack track =
                                        playlist.tracks.get(
                                                trackIndex
                                        );

                                try {

                                    if (
                                            track == null ||
                                            track.artist == null ||
                                            track.title == null ||
                                            (
                                                    track.artist.trim().isEmpty() &&
                                                    track.title.trim().isEmpty()
                                            )
                                    ) {

                                        return new java.util.AbstractMap.SimpleEntry<>(
                                                trackIndex,
                                                null
                                        );
                                    }

                                    SpotifyResolvedTrack resolvedResult =
                                            resolveSpotifyTrackWithRetry(
                                                    track.artist,
                                                    track.title
                                            );

                                    ApiClient.Song resolved =
                                            resolvedResult.resolved;

                                    String url =
                                            resolvedResult.url;

                                    MediaMetadata.Builder metadata =
                                            new MediaMetadata.Builder()
                                                    .setTitle(
                                                            track.title
                                                    );

                                    if (
                                            track.artist != null &&
                                            !track.artist.trim().isEmpty()
                                    ) {

                                        metadata.setArtist(
                                                track.artist
                                        );
                                    }

                                    if (
                                            track.album != null &&
                                            !track.album.trim().isEmpty()
                                    ) {

                                        metadata.setAlbumTitle(
                                                track.album
                                        );
                                    }

                                    String thumbnail =
                                            track.thumbnail;

                                    if (
                                            (thumbnail == null ||
                                                    thumbnail.trim().isEmpty()) &&
                                            resolved.thumbnail != null &&
                                            !resolved.thumbnail.trim().isEmpty()
                                    ) {

                                        thumbnail =
                                                resolved.thumbnail;
                                    }

                                    if (
                                            thumbnail != null &&
                                            !thumbnail.trim().isEmpty()
                                    ) {

                                        metadata.setArtworkUri(
                                                Uri.parse(thumbnail)
                                        );
                                    }

                                    MediaItem item =
                                            new MediaItem.Builder()
                                                    .setUri(url)
                                                    .setMediaMetadata(
                                                            metadata.setExtras(queueDurationExtras(track.duration)).build()
                                                    )
                                                    .build();

                                    return new java.util.AbstractMap.SimpleEntry<>(
                                            trackIndex,
                                            item
                                    );

                                } catch (Exception error) {

                                    return new java.util.AbstractMap.SimpleEntry<>(
                                            trackIndex,
                                            null
                                    );
                                }
                            });
                        }

                        retryResolver.shutdown();

                        java.util.Map<Integer, MediaItem> retryReady =
                                new java.util.HashMap<>();

                        for (
                                int completed = 0;
                                completed < failedBatchSize;
                                completed++
                        ) {

                            java.util.AbstractMap.SimpleEntry<
                                    Integer,
                                    MediaItem
                                    > result =
                                    retryCompletion.take().get();

                            retryReady.put(
                                    result.getKey(),
                                    result.getValue()
                            );
                        }

                        for (
                                int position = failedStart;
                                position < failedEnd;
                                position++
                        ) {

                            int trackIndex =
                                    failedSpotifyIndexes.get(
                                            position
                                    );

                            MediaItem item =
                                    retryReady.get(
                                            trackIndex
                                    );

                            if (item == null) {

                                secondPassFailed.add(
                                        trackIndex
                                );

                                continue;
                            }

                            List<MediaItem> one =
                                    new ArrayList<>();

                            one.add(item);

                            addedCount++;

                            resolvedSpotifyItems.put(
                                    trackIndex,
                                    item
                            );

                            final int preparedTrackIndex =
                                    trackIndex;

                            updateQueuePreparationProgress(
                                    queueGeneration,
                                    addedCount,
                                    playlistTotal
                            );

                            markSpotifyTrackObtained(
                                    queueGeneration,
                                    preparedTrackIndex
                            );

                            handler.post(() -> {

                                if (!isCurrentIndividualPlayback(
                                        playbackGeneration)) {
                                    return;
                                }

                                insertSpotifyRecoveredItemIntoQueue(
                                        one.get(0),
                                        preparedTrackIndex,
                                        total,
                                        resolvedSpotifyItems
                                );
                            });
                        }

                        failedStart =
                                failedEnd;
                    }

                    failedSpotifyIndexes =
                            secondPassFailed;
                }

                final int finalAddedCount =
                        addedCount;

                handler.post(() ->
                        Toast.makeText(
                                this,
                                "Spotify preparado: "
                                        + finalAddedCount
                                        + " canciones",
                                Toast.LENGTH_SHORT
                        ).show()
                );

            } catch (Exception error) {

                handler.post(
                        () -> showError(error)
                );
            }
        });
    }

    private void playSpotifyTrack(
            ApiClient.SpotifyTrack track) {

        Toast.makeText(
                this,
                "Buscando audio: "
                        + track.title,
                Toast.LENGTH_SHORT
        ).show();

        executor.execute(() -> {

            try {

                SpotifyResolvedTrack resolvedResult =
                        resolveSpotifyTrackWithRetry(
                                track.artist,
                                track.title
                        );

                ApiClient.Song resolved =
                        resolvedResult.resolved;

                String url =
                        resolvedResult.url;

                String thumbnail =
                        track.thumbnail;

                if (
                        (thumbnail == null ||
                                thumbnail.trim().isEmpty()) &&
                        resolved.thumbnail != null &&
                        !resolved.thumbnail.trim().isEmpty()
                ) {
                    thumbnail =
                            resolved.thumbnail;
                }

                final String finalThumbnail =
                        thumbnail;

                handler.post(
                        () -> playResolved(
                                resolved.id,
                                url,
                                track.artist
                                        + " - "
                                        + track.title,
                                finalThumbnail
                        )
                );

            } catch (Exception e) {

                handler.post(
                        () -> showError(e)
                );
            }
        });
    }

    private static class SpotifyResolvedTrack {

        final ApiClient.Song resolved;
        final String url;

        SpotifyResolvedTrack(
                ApiClient.Song resolved,
                String url) {

            this.resolved = resolved;
            this.url = url;
        }
    }

    /*
     * Resuelve una canción de Spotify de principio a fin.
     *
     * Si cambia Wi-Fi <-> 4G durante cualquiera de las peticiones,
     * conserva artista + título y vuelve a empezar el proceso.
     *
     * Cada intento utiliza un ApiClient nuevo.
     * Tiempo máximo: 60 segundos.
     * Espera entre intentos: 3 segundos.
     */
    private SpotifyResolvedTrack resolveSpotifyTrackWithRetry(
            String artist,
            String title) throws Exception {

        final long retryDeadline =
                System.currentTimeMillis() + 60000L;

        Exception lastError = null;

        while (
                System.currentTimeMillis() <
                retryDeadline
        ) {

            try {

                ApiClient.Song resolved =
                        api().resolveAlbumTrack(
                                artist,
                                title
                        );

                if (
                        resolved == null ||
                        resolved.id == null ||
                        resolved.id.trim().isEmpty()
                ) {
                    throw new Exception(
                            "No se pudo obtener videoId"
                    );
                }

                String url =
                        api().getAudioUrl(
                                resolved.id
                        );

                if (
                        url == null ||
                        url.trim().isEmpty()
                ) {
                    throw new Exception(
                            "No se obtuvo URL de reproducción"
                    );
                }

                return new SpotifyResolvedTrack(
                        resolved,
                        url
                );

            } catch (Exception error) {

                lastError = error;

                try {

                    Thread.sleep(3000L);

                } catch (InterruptedException interrupted) {

                    Thread.currentThread().interrupt();
                    throw interrupted;
                }
            }
        }

        if (lastError != null) {
            throw lastError;
        }

        throw new Exception(
                "Tiempo agotado esperando conexión"
        );
    }

    private void playSpotifyPlaylist(
            ApiClient.SpotifyPlaylist playlist) {

        final long playbackGeneration =
                beginIndividualPlayback();


        final int playlistTotal =
                playlist != null &&
                playlist.tracks != null
                        ? playlist.tracks.size()
                        : 0;

        final long queueGeneration =
                beginQueuePreparation(
                        playlistTotal
                );

Toast.makeText(
                this,
                "Preparando primera canción...",
                Toast.LENGTH_LONG
        ).show();

        executor.execute(() -> {

            try {

                final int count =
                        playlist.tracks.size();

                if (count == 0) {

                    handler.post(() -> {
                        if (!isCurrentIndividualPlayback(
                                playbackGeneration)) {
                            return;
                        }

                        Toast.makeText(
                                this,
                                "La playlist no tiene canciones",
                                Toast.LENGTH_SHORT
                        ).show();
                    });

                    return;
                }

                /*
                 * =========================================================
                 * 1. RESOLVER PRIMERO LA PRIMERA CANCIÓN
                 * =========================================================
                 */

                ApiClient.SpotifyTrack firstTrack =
                        playlist.tracks.get(0);

                if (
                        firstTrack.artist.isEmpty() &&
                        firstTrack.title.isEmpty()
                ) {

                    handler.post(() -> {
                        if (!isCurrentIndividualPlayback(
                                playbackGeneration)) {
                            return;
                        }

                        Toast.makeText(
                                this,
                                "No se pudo resolver la primera canción",
                                Toast.LENGTH_SHORT
                        ).show();
                    });

                    return;
                }

                SpotifyResolvedTrack firstResolvedResult =
                        resolveSpotifyTrackWithRetry(
                                firstTrack.artist,
                                firstTrack.title
                        );

                ApiClient.Song firstResolved =
                        firstResolvedResult.resolved;

                String firstUrl =
                        firstResolvedResult.url;

                MediaMetadata.Builder firstMetadata =
                        new MediaMetadata.Builder()
                                .setTitle(
                                        firstTrack.title
                                );

                if (!firstTrack.artist.isEmpty()) {

                    firstMetadata.setArtist(
                            firstTrack.artist
                    );
                }

                if (
                        firstTrack.album != null &&
                        !firstTrack.album.isEmpty()
                ) {

                    firstMetadata.setAlbumTitle(
                            firstTrack.album
                    );
                }

                String firstThumbnail =
                        firstTrack.thumbnail;

                if (
                        (firstThumbnail == null ||
                                firstThumbnail.trim().isEmpty()) &&
                        firstResolved.thumbnail != null &&
                        !firstResolved.thumbnail.trim().isEmpty()
                ) {
                    firstThumbnail =
                            firstResolved.thumbnail;
                }

                if (
                        firstThumbnail != null &&
                        !firstThumbnail.trim().isEmpty()
                ) {
                    firstMetadata.setArtworkUri(
                            Uri.parse(firstThumbnail)
                    );
                }

                MediaItem firstItem =
                        new MediaItem.Builder()
                                .setUri(firstUrl)
                                .setMediaMetadata(
                                        firstMetadata.setExtras(queueDurationExtras(firstTrack.duration)).build()
                                )
                                .build();

                List<MediaItem> firstList =
                        new ArrayList<>();

                firstList.add(firstItem);

                /*
                 * =========================================================
                 * 2. ARRANCAR LA REPRODUCCIÓN
                 * =========================================================
                 */

                handler.post(() -> {

                    if (!isCurrentIndividualPlayback(
                            playbackGeneration)) {
                        return;
                    }

                    sendQueueToPlayer(firstList);

                    updateQueuePreparationProgress(
                            queueGeneration,
                            1,
                            playlistTotal
                    );

                    markSpotifyTrackObtained(
                            queueGeneration,
                            0
                    );
                });

                if (count == 1) {

                    handler.post(() -> {

                        if (!isCurrentIndividualPlayback(
                                playbackGeneration)) {
                            return;
                        }

                        Toast.makeText(
                                this,
                                "Spotify preparado: 1 canción",
                                Toast.LENGTH_SHORT
                        ).show();
                    });

                    return;
                }

                /*
                 * =========================================================
                 * 3. RESOLVER EL RESTO EN SEGUNDO PLANO
                 * =========================================================
                 */

                ExecutorService resolver =
                        Executors.newFixedThreadPool(
                                Math.min(
                                        6,
                                        Math.max(
                                                1,
                                                count - 1
                                        )
                                )
                        );

                java.util.concurrent.ExecutorCompletionService<
                        java.util.AbstractMap.SimpleEntry<
                                Integer,
                                MediaItem
                        >
                        > completionService =
                        new java.util.concurrent.ExecutorCompletionService<>(
                                resolver
                        );

                int submitted = 0;

                for (int index = 1; index < count; index++) {

                    final int trackIndex = index;

                    completionService.submit(() -> {

                        ApiClient.SpotifyTrack track =
                                playlist.tracks.get(trackIndex);

                        try {

                            if (
                                    track.artist.isEmpty() &&
                                    track.title.isEmpty()
                            ) {
                                return new java.util.AbstractMap.SimpleEntry<>(
                                        trackIndex,
                                        null
                                );
                            }

                            SpotifyResolvedTrack resolvedResult =
                                    resolveSpotifyTrackWithRetry(
                                            track.artist,
                                            track.title
                                    );

                            ApiClient.Song resolved =
                                    resolvedResult.resolved;

                            String url =
                                    resolvedResult.url;

                            MediaMetadata.Builder metadata =
                                    new MediaMetadata.Builder()
                                            .setTitle(
                                                    track.title
                                            );

                            if (!track.artist.isEmpty()) {

                                metadata.setArtist(
                                        track.artist
                                );
                            }

                            if (
                                    track.album != null &&
                                    !track.album.isEmpty()
                            ) {

                                metadata.setAlbumTitle(
                                        track.album
                                );
                            }

                            String thumbnail =
                                    track.thumbnail;

                            if (
                                    (thumbnail == null ||
                                            thumbnail.trim().isEmpty()) &&
                                    resolved.thumbnail != null &&
                                    !resolved.thumbnail.trim().isEmpty()
                            ) {
                                thumbnail =
                                        resolved.thumbnail;
                            }

                            if (
                                    thumbnail != null &&
                                    !thumbnail.trim().isEmpty()
                            ) {
                                metadata.setArtworkUri(
                                        Uri.parse(thumbnail)
                                );
                            }

                            MediaItem item =
                                    new MediaItem.Builder()
                                            .setUri(url)
                                            .setMediaMetadata(
                                                    metadata.setExtras(queueDurationExtras(track.duration)).build()
                                            )
                                            .build();

                            return new java.util.AbstractMap.SimpleEntry<>(
                                    trackIndex,
                                    item
                            );

                        } catch (Exception error) {

                            System.err.println(
                                    "Spotify: no se pudo resolver "
                                            + "la canción "
                                            + (trackIndex + 1)
                                            + ": "
                                            + error
                            );

                            return new java.util.AbstractMap.SimpleEntry<>(
                                    trackIndex,
                                    null
                            );
                        }
                    });

                    submitted++;
                }

                /*
                 * =========================================================
                 * 4. RECIBIR RESULTADOS SEGÚN TERMINEN
                 * =========================================================
                 */

                java.util.Map<Integer, MediaItem> ready =
                        new java.util.HashMap<>();

                int nextIndex = 1;
                int completed = 0;
                int addedCount = 1;

                while (completed < submitted) {

                    java.util.concurrent.Future<
                            java.util.AbstractMap.SimpleEntry<
                                    Integer,
                                    MediaItem
                            >
                            > future =
                            completionService.take();

                    java.util.AbstractMap.SimpleEntry<
                            Integer,
                            MediaItem
                            > result =
                            future.get();

                    completed++;

                    int resultIndex =
                            result.getKey();

                    MediaItem resultItem =
                            result.getValue();

                    /*
                     * Si ya hemos empezado otra reproducción,
                     * no seguimos preparando esta playlist.
                     */
                    if (!isCurrentIndividualPlayback(
                            playbackGeneration)) {
                        break;
                    }

                    ready.put(
                            resultIndex,
                            resultItem
                    );

                    /*
                     * =====================================================
                     * Añadir solamente elementos consecutivos.
                     * =====================================================
                     */

                    while (
                            ready.containsKey(nextIndex)
                    ) {

                        MediaItem item =
                                ready.remove(nextIndex);

                        nextIndex++;

                        if (item == null) {

                            System.err.println(
                                    "Spotify: se omite la canción "
                                            + nextIndex
                                            + " porque no pudo resolverse"
                            );

                            continue;
                        }

                        List<MediaItem> one =
                                new ArrayList<>();

                        one.add(item);

                        int preparedTrackIndex =
                                nextIndex - 1;

                        addedCount++;

                        updateQueuePreparationProgress(
                                queueGeneration,
                                addedCount,
                                playlistTotal
                        );

                        markSpotifyTrackObtained(
                                queueGeneration,
                                preparedTrackIndex
                        );

                        handler.post(() -> {

                            if (!isCurrentIndividualPlayback(
                                    playbackGeneration)) {
                                return;
                            }

                            addItemsToPlayerQueue(one);
                        });
                    }
                }

                resolver.shutdown();

                final int finalAddedCount =
                        addedCount;

                handler.post(() -> {

                    if (!isCurrentIndividualPlayback(
                            playbackGeneration)) {
                        return;
                    }

                    Toast.makeText(
                            this,
                            "Spotify preparado: "
                                    + finalAddedCount
                                    + " canciones",
                            Toast.LENGTH_SHORT
                    ).show();
                });

            } catch (Exception e) {

                handler.post(() -> {

                    if (!isCurrentIndividualPlayback(
                            playbackGeneration)) {
                        return;
                    }

                    showError(e);
                });
            }
        });
    }

