    private void watchDownloadJob(
            String job,
            DownloadSlot slot) {

        final Handler pollHandler =
                new Handler(
                        Looper.getMainLooper()
                );

        final Runnable[] checker =
                new Runnable[1];

        checker[0] = () -> {

            executor.execute(() -> {

                try {

                    JSONObject data =
                            api().getDownloadStatus(
                                    job
                            );

                    String state =
                            data.optString(
                                    "status",
                                    ""
                            );

                    int progressValue =
                            data.optInt(
                                    "progress",
                                    0
                            );

                    String message =
                            data.optString(
                                    "message",
                                    ""
                            );

                    handler.post(() -> {

                        slot.progress.setProgress(
                                Math.max(
                                        0,
                                        Math.min(
                                                100,
                                                progressValue
                                        )
                                )
                        );

                        if ("queued".equals(state)) {

                            slot.status.setText(
                                    "🕐 Procesando cola..."
                            );

                        } else if ("running".equals(state)) {

                            if (
                                    message.contains(
                                            "Procesando etiquetas"
                                    )
                            ) {

                                slot.status.setText(
                                        "🖼️ Procesando etiquetas y portada..."
                                );

                            } else if (
                                    message.contains(
                                            "Descargando"
                                    )
                            ) {

                                slot.status.setText(
                                        "⬇️ " + message
                                );

                            } else {

                                slot.status.setText(
                                        "⬇️ Descargando... "
                                                + progressValue
                                                + "%"
                                );
                            }

                        } else if ("done".equals(state)) {

                            saveServerDownloadedV2(
                                    slot.title,
                                    slot.track != null ? slot.track.artist :
                                    slot.albumTrack != null ? slot.albumTrack.artist : ""
                            );

                            saveServerDownloadIdV2(slot.videoId);
                            slot.progress.setProgress(100);

                            slot.status.setText(
                                    "✓ DESCARGADA"
                            );

                            slot.button.setText(
                                    "✓ Descargada"
                            );

                            slot.button.setEnabled(false);

                            handler.postDelayed(() -> {

                                slot.status.setText(
                                        "🎧 ENVIADA A NAVIDROME"
                                );

                                slot.button.setText(
                                        "✓ Completado"
                                );

                            }, 700);

                            return;

                        } else if ("error".equals(state)) {

                            slot.status.setText(
                                    "❌ "
                                            + (
                                            message.isEmpty()
                                                    ? "Error durante la descarga"
                                                    : message
                                    )
                            );

                            slot.button.setText(
                                    "↻ Reintentar"
                            );

                            slot.button.setEnabled(true);

                            return;
                        }

                        pollHandler.postDelayed(
                                checker[0],
                                1500
                        );
                    });

                } catch (Exception e) {

                    handler.post(() -> {

                        slot.status.setText(
                                "❌ Error consultando descarga"
                        );

                        slot.button.setText(
                                "↻ Reintentar"
                        );

                        slot.button.setEnabled(true);
                    });
                }
            });
        };

        pollHandler.post(checker[0]);
    }


    // V2: registro persistente independiente de las vistas de descarga.
    // No altera la cola, el reproductor ni el flujo de transferencia existente.
    private void recordMobileJobV2(String job, String state,
                                   DownloadSlot slot, String format) {
        try {
            new MobileDownloadJournal(getApplicationContext())
                    .put(job, state, slot.title, format,
                            slot.track != null ? slot.track.artist :
                                (slot.albumTrack != null ? slot.albumTrack.artist : ""),
                            slot.track != null ? slot.track.album :
                                (slot.albumTrack != null ? slot.albumTrack.album :
                                    (slot.albumTitle != null ? slot.albumTitle : "")),
                            slot.track != null ? slot.track.thumbnail :
                                (slot.albumTrack != null ? slot.albumTrack.thumbnail : ""),
                            slot.videoId.isEmpty() && slot.albumTrack != null ?
                                slot.albumTrack.videoId : slot.videoId,
                            slot.track != null ? slot.track.duration :
                                (slot.albumTrack != null ? slot.albumTrack.duration : 0));
            // El servicio es el único propietario de las transferencias V2.
            MobileDownloadRecoveryService.schedule(getApplicationContext());
            MobileDownloadForegroundService.start(getApplicationContext());
        } catch (Exception failure) {
            Log.e("MobileDownloadV2", "No se pudo registrar/iniciar la descarga persistente", failure);
        }
    }

    private void updateMobileJobV2(String job, String state) {
        try {
            new MobileDownloadJournal(getApplicationContext())
                    .updateState(job, state);
        } catch (Exception ignored) {
            // Se preserva el comportamiento existente si el registro falla.
        }
    }


    // V2: seguimiento exclusivamente visual.
    // El servicio de recuperación es el único que descarga y guarda archivos.
    private void watchMobileDownloadJobV2Visual(
            String job,
            DownloadSlot slot) {

        final Handler visualHandler =
                new Handler(Looper.getMainLooper());

        final Runnable[] checker = new Runnable[1];

        checker[0] = () -> executor.execute(() -> {

            String journalState = "";
            try {
                for (MobileDownloadJournal.Entry entry :
                        new MobileDownloadJournal(getApplicationContext()).list()) {
                    if (job.equals(entry.jobId)) {
                        journalState = entry.state;
                        break;
                    }
                }
            } catch (Exception ignored) {
            }

            final String localState = journalState;

            if ("completed".equals(localState)) {
                handler.post(() -> {
                    slot.progress.setProgress(100);
                    slot.status.setText("✓ DESCARGA OFFLINE COMPLETADA");
                    slot.button.setText("✓ Offline");
                    slot.button.setEnabled(false);
                    finishMobileDownloadMonitor(
                            job, "✓ DESCARGA OFFLINE COMPLETADA");
                });
                return;
            }

            if ("failed".equals(localState)
                    || "error".equals(localState)
                    || "cancelled".equals(localState)) {
                handler.post(() -> {
                    String status = "❌ Descarga offline: " + localState;
                    slot.status.setText(status);
                    slot.button.setText("↻ Reintentar");
                    slot.button.setEnabled(true);
                    updateMobileDownloadMonitor(
                            job, slot.progress.getProgress(), status);
                });
                return;
            }

            if ("ready".equals(localState)
                    || "transferred".equals(localState)
                    || "saving".equals(localState)) {

                final String status =
                        "saving".equals(localState)
                                ? "📱 Guardando canción offline..."
                                : "transferred".equals(localState)
                                        ? "📱 Preparando guardado offline..."
                                        : "📱 Transfiriendo canción al móvil...";

                handler.post(() -> {
                    slot.progress.setProgress(99);
                    slot.status.setText(status);
                    updateMobileDownloadMonitor(job, 99, status);
                    visualHandler.postDelayed(checker[0], 1500);
                });
                return;
            }

            try {
                JSONObject data = api().getDownloadStatus(job);

                String serverState =
                        data.optString("status", "");

                int serverProgress =
                        Math.max(0, Math.min(100,
                                data.optInt("progress", 0)));

                String message =
                        data.optString("message", "");

                final int displayProgress =
                        Math.min(98, serverProgress);

                final String status;

                if ("done".equals(serverState)
                        || "completed".equals(serverState)) {
                    status = "📱 Preparando transferencia al móvil...";
                } else if ("running".equals(serverState)
                        || "downloading".equals(serverState)
                        || "processing".equals(serverState)) {
                    status = message.isEmpty()
                            ? "⬇ Descargando canción..."
                            : "⬇ " + message;
                } else if ("queued".equals(serverState)
                        || "pending".equals(serverState)) {
                    status = "🕐 Esperando turno de descarga...";
                } else if ("error".equals(serverState)
                        || "failed".equals(serverState)) {
                    status = "❌ " + (
                            message.isEmpty()
                                    ? "Error del servidor"
                                    : message);
                } else {
                    status = "📱 Preparando descarga offline...";
                }

                handler.post(() -> {
                    slot.progress.setProgress(displayProgress);
                    slot.status.setText(status);

                    updateMobileDownloadMonitor(
                            job, displayProgress, status);

                    if ("error".equals(serverState)
                            || "failed".equals(serverState)) {
                        slot.button.setText("↻ Reintentar");
                        slot.button.setEnabled(true);
                    } else {
                        visualHandler.postDelayed(
                                checker[0], 1500);
                    }
                });

            } catch (Exception ignored) {
                handler.post(() -> {
                    slot.status.setText(
                            "🔄 Reconectando con el servidor...");
                    visualHandler.postDelayed(
                            checker[0], 3000);
                });
            }
        });

        visualHandler.post(checker[0]);
    }

    private void watchMobileDownloadJob(
            String job,
            DownloadSlot slot) {

        ;

        final PowerManager powerManager =
                (PowerManager) getSystemService(
                        POWER_SERVICE
                );

        final PowerManager.WakeLock wakeLock =
                powerManager.newWakeLock(
                        PowerManager.PARTIAL_WAKE_LOCK,
                        "MusicDownloader:OfflineDownload"
                );

        wakeLock.setReferenceCounted(false);

        if (!wakeLock.isHeld()) {
            wakeLock.acquire();
        }

        ;

        final Handler pollHandler =
                new Handler(
                        Looper.getMainLooper()
                );

        final Runnable[] checker =
                new Runnable[1];

        checker[0] = () -> {

            ;

            executor.execute(() -> {

                try {

                    JSONObject data =
                            api().getDownloadStatus(job);

                    ;

                    String state =
                            data.optString(
                                    "status",
                                    ""
                            );

                    int progress =
                            data.optInt(
                                    "progress",
                                    0
                            );

                    String message =
                            data.optString(
                                    "message",
                                    ""
                            );

                    ;

                    if ("done".equals(state)) {
                        updateMobileJobV2(job, "transferring");
                    } else if ("error".equals(state)
                            || "cancelled".equals(state)) {
                        updateMobileJobV2(job, state);
                    }

                    handler.post(() -> {

                        ;

                        int safeProgress =
                                Math.max(
                                        0,
                                        Math.min(
                                                100,
                                                progress
                                        )
                                );

                        slot.progress.setProgress(
                                safeProgress
                        );

                        String monitorStatus =
                                "📱 "
                                        + (
                                        message.isEmpty()
                                                ? "Preparando canción..."
                                                : message
                                );

                        updateMobileDownloadMonitor(
                                job,
                                safeProgress,
                                monitorStatus
                        );

                        if ("queued".equals(state)
                                || "running".equals(state)
                                || "downloading".equals(state)
                                || "processing".equals(state)) {

                            ;

                            slot.status.setText(
                                    "📱 "
                                            + (
                                            message.isEmpty()
                                                    ? "Preparando canción..."
                                                    : message
                                    )
                            );

                            slot.button.setText(
                                    "⬇ Preparando..."
                            );

                            pollHandler.postDelayed(
                                    checker[0],
                                    1500
                            );

                        } else if ("done".equals(state)) {

                            ;

                            slot.progress.setProgress(
                                    99
                            );

                            slot.status.setText(
                                    "✓ DESCARGADA"
                            );

                            slot.button.setText(
                                    "✓ Descargada"
                            );

                            updateMobileDownloadMonitor(
                                    job,
                                    99,
                                    "✓ DESCARGADA"
                            );

                            saveMobileDownload(
                                    job,
                                    slot,
                                    data,
                                    wakeLock
                            );

                            ;

                        } else if ("cancelled".equals(state)) {

                            ;

                            String cancelledStatus =
                                    "✕ "
                                            + (
                                            message.isEmpty()
                                                    ? "Descarga cancelada."
                                                    : message
                                    );

                            slot.status.setText(
                                    cancelledStatus
                            );

                            updateMobileDownloadMonitor(
                                    job,
                                    progress,
                                    cancelledStatus
                            );

                            slot.button.setText(
                                    "↻ Reintentar"
                            );

                            slot.button.setEnabled(
                                    true
                            );

                            if (wakeLock.isHeld()) {
                                wakeLock.release();
                            }

                            ;

                        } else if ("error".equals(state)) {

                            ;

                            String errorStatus =
                                    "❌ "
                                            + (
                                            message.isEmpty()
                                                    ? "Error durante la descarga offline"
                                                    : message
                                    );

                            slot.status.setText(
                                    errorStatus
                            );

                            updateMobileDownloadMonitor(
                                    job,
                                    progress,
                                    errorStatus
                            );

                            slot.button.setText(
                                    "↻ Reintentar"
                            );

                            slot.button.setEnabled(
                                    true
                            );

                            if (wakeLock.isHeld()) {
                                wakeLock.release();
                            }

                            ;

                        } else {

                            ;

                            pollHandler.postDelayed(
                                    checker[0],
                                    1500
                            );
                        }
                    });

                } catch (Exception e) {

                    ;

                    handler.post(() -> {

                        slot.status.setText(
                                "🔄 Reintentando consultar descarga..."
                        );

                        slot.button.setText(
                                "⬇ Preparando..."
                        );

                        slot.button.setEnabled(
                                false
                        );

                        pollHandler.postDelayed(
                                checker[0],
                                2000
                        );
                    });
                }
            });
        };

        pollHandler.post(
                checker[0]
        );
    }


    private void saveMobileDownload(
            String job,
            DownloadSlot slot,
            JSONObject data,
            PowerManager.WakeLock wakeLock) {

        final long saveStartTime =
                System.currentTimeMillis();

        ;

        executor.execute(() -> {

            ;

            HttpURLConnection connection = null;

            try {

                if (offlineFolderUri == null) {
                    throw new Exception(
                            "No hay carpeta offline seleccionada."
                    );
                }

                ;

                DocumentFile folder =
                        DocumentFile.fromTreeUri(
                                this,
                                offlineFolderUri
                        );

                ;

                if (folder == null
                        || !folder.isDirectory()
                        || !folder.canWrite()) {

                    throw new Exception(
                            "La carpeta offline no está disponible."
                    );
                }

                String format =
                        data.optString(
                                "format",
                                ""
                        );

                String filename =
                        data.optString(
                                "filename",
                                ""
                        );

                if (
                        !"opus".equalsIgnoreCase(format) &&
                        !"mp3".equalsIgnoreCase(format)
                ) {

                    if (
                            filename
                                    .toLowerCase()
                                    .endsWith(".opus")
                    ) {
                        format = "opus";
                    } else {
                        format = "mp3";
                    }

                } else {

                    format =
                            "opus".equalsIgnoreCase(format)
                                    ? "opus"
                                    : "mp3";
                }

                final String extension =
                        "opus".equals(format)
                                ? ".opus"
                                : ".mp3";

                final String mimeType =
                        "opus".equals(format)
                                ? "audio/ogg"
                                : "audio/mpeg";

                if (filename.isEmpty()) {
                    filename = slot.title + extension;
                }

                filename =
                        filename
                                .replace(
                                        "/",
                                        "_"
                                )
                                .replace(
                                        "\\",
                                        "_"
                                )
                                .trim();

                String lowerFilename =
                        filename.toLowerCase();

                if (
                        lowerFilename.endsWith(".mp3") ||
                        lowerFilename.endsWith(".opus")
                ) {

                    int dot =
                            filename.lastIndexOf(".");

                    if (dot >= 0) {

                        filename =
                                filename.substring(
                                        0,
                                        dot
                                )
                                + extension;
                    }

                } else {

                    filename += extension;
                }

                String finalFilename = filename;

                DocumentFile target =
                        folder.findFile(
                                finalFilename
                        );

                if (target != null) {

                    String base =
                            finalFilename.substring(
                                    0,
                                    finalFilename.length()
                                            - extension.length()
                            );

                    int counter = 2;

                    do {

                        finalFilename =
                                base
                                        + " ("
                                        + counter
                                        + ")"
                                        + extension;

                        target =
                                folder.findFile(
                                        finalFilename
                                );

                        counter++;

                    } while (target != null);
                }

                ;

                ;

                target =
                        folder.createFile(
                                mimeType,
                                finalFilename
                        );

                ;

                if (target == null) {
                    throw new Exception(
                            "No se pudo crear el archivo en la carpeta offline."
                    );
                }

                ;

                URL url =
                        new URL(
                                api().getMobileDownloadUrl(
                                        job
                                )
                        );

                connection =
                        (HttpURLConnection)
                                url.openConnection();

                connection.setRequestMethod(
                        "GET"
                );

                connection.setConnectTimeout(
                        15000
                );

                connection.setReadTimeout(
                        120000
                );

                connection.setRequestProperty(
                        "Accept",
                        mimeType
                );

                connection.setRequestProperty(
                        "Accept-Encoding",
                        "identity"
                );

                connection.setRequestProperty(
                        "Connection",
                        "close"
                );

                connection.setUseCaches(false);

                ;

                ;

                int responseCode =
                        connection.getResponseCode();

                ;

                ;

                if (responseCode != HttpURLConnection.HTTP_OK) {
                    throw new Exception(
                            "El servidor respondió HTTP "
                                    + responseCode
                    );
                }

                long totalBytes =
                        connection.getContentLengthLong();

                ;

                long downloadedBytes = 0;
                long lastLoggedBytes = 0;
                final long LOG_INTERVAL =
                        1024L * 1024L;

                try (
                        InputStream input =
                                connection.getInputStream();

                        OutputStream output =
                                getContentResolver()
                                        .openOutputStream(
                                                target.getUri()
                                        )
                ) {

                    if (output == null) {
                        throw new Exception(
                                "No se pudo abrir el archivo offline."
                        );
                    }

                    ;

                    ;

                    byte[] buffer =
                            new byte[256 * 1024];

                    int count;

                    while (
                            (count =
                                    input.read(buffer))
                                    != -1
                    ) {

                        if (count == 0) {
                            continue;
                        }

                        output.write(
                                buffer,
                                0,
                                count
                        );

                        downloadedBytes += count;

                        if (downloadedBytes - lastLoggedBytes
                                >= LOG_INTERVAL) {

                            lastLoggedBytes =
                                    downloadedBytes;

                            ;
                        }

                        if (totalBytes > 0) {

                            int transferProgress =
                                    (int)
                                            (
                                                    downloadedBytes
                                                            * 100L
                                                            / totalBytes
                                            );

                            final int currentProgress =
                                    Math.min(
                                            100,
                                            transferProgress
                                    );

                            handler.post(() ->
                                    slot.progress.setProgress(
                                            currentProgress
                                    )
                            );
                        }
                    }

                    output.flush();

                    ;
                }

                ;

                if (totalBytes > 0
                        && downloadedBytes != totalBytes) {

                    throw new Exception(
                            "Transferencia incompleta: "
                                    + downloadedBytes
                                    + " de "
                                    + totalBytes
                                    + " bytes."
                    );
                }

                ;

                final long finalSize =
                        downloadedBytes;

                final String savedUri =
                        target.getUri().toString();

                final String savedFilename =
                        finalFilename;

                updateMobileJobV2(job, "completed");

                addOfflineTrack(
                        savedUri,
                        savedFilename,
                        finalSize,
                        slot.videoId,
                        slot.title,
                        getOfflineArtist(slot),
                        getOfflineAlbum(slot),
                        getOfflineDuration(slot),
                        getOfflineThumbnail(slot)
                );

                handler.post(() -> {

                    slot.progress.setProgress(
                            100
                    );

                    slot.status.setText(
                            "📱 ENVIADA AL MÓVIL"
                    );

                    slot.button.setText(
                            "✓ Offline"
                    );

                    slot.button.setEnabled(
                            false
                    );

                    finishMobileDownloadMonitor(
                            job,
                            "📱 ENVIADA AL MÓVIL"
                    );

                    Toast.makeText(
                            this,
                            "📱 Canción enviada al móvil",
                            Toast.LENGTH_SHORT
                    ).show();
                });

            } catch (Exception e) {

                updateMobileJobV2(job, "transfer_failed");

                ;

                handler.post(() -> {

                    String saveErrorStatus =
                            "❌ "
                                    + (
                                    e.getMessage() == null
                                            ? "Error guardando la canción"
                                            : e.getMessage()
                            );

                    slot.status.setText(
                            saveErrorStatus
                    );

                    updateMobileDownloadMonitor(
                            job,
                            slot.progress.getProgress(),
                            saveErrorStatus
                    );

                    slot.button.setText(
                            "↻ Reintentar"
                    );

                    slot.button.setEnabled(
                            true
                    );
                });

            } finally {

                if (connection != null) {
                    connection.disconnect();
                }

                if (wakeLock != null && wakeLock.isHeld()) {
                    wakeLock.release();

                    ;
                }
            }
        });
    }

    private String getOfflineFormat() {

        String format =
                getSharedPreferences(
                        "settings",
                        MODE_PRIVATE
                ).getString(
                        "offline_format",
                        "mp3"
                );

        if ("opus".equalsIgnoreCase(format)) {
            return "opus";
        }

        return "mp3";
    }

    private void saveOfflineFormat(
            String format) {

        if ("opus".equalsIgnoreCase(format)) {
            format = "opus";
        } else {
            format = "mp3";
        }

        getSharedPreferences(
                "settings",
                MODE_PRIVATE
        ).edit()
                .putString(
                        "offline_format",
                        format
                )
                .apply();
    }

    private void startMobileDownload(
            DownloadSlot slot) {

        ;

        if (offlineFolderUri == null) {

            ;

            Toast.makeText(
                    this,
                    "📂 Selecciona primero la carpeta offline",
                    Toast.LENGTH_LONG
            ).show();

            chooseOfflineFolder();
            return;
        }

        ;

        ;

        slot.button.setEnabled(false);

        slot.button.setText(
                "⏳ Preparando..."
        );

        slot.status.setText(
                "📱 Preparando descarga offline..."
        );

        slot.progress.setProgress(0);

        final String offlineFormat =
                getOfflineFormat();


        executor.execute(() -> {

            try {

                ;

                JSONObject result;

                if (
                        slot.albumGroup != null &&
                        !slot.albumGroup.isEmpty()
                ) {

                    result =
                            api().downloadMobile(
                                slot.videoId,
                                slot.title,
                                slot.albumGroup,
                                slot.albumTitle,
                                slot.albumTrackIndex,
                                slot.albumTrackTotal,
                                offlineFormat
                        );

                } else {

                    result =
                            api().downloadMobile(
                                slot.videoId,
                                slot.title,
                                null,
                                null,
                                0,
                                0,
                                offlineFormat
                        );
                }

                ;

                String job =
                        result.optString(
                                "job",
                                ""
                        );

                ;

                if (job.isEmpty()) {

                    throw new Exception(
                            "El servidor no devolvió el trabajo offline."
                    );
                }

                registerMobileDownload(
                        job,
                        slot
                );

                recordMobileJobV2(
                        job,
                        "preparing",
                        slot,
                        offlineFormat
                );

                // Monitor visual V2: nunca descarga ni publica archivos.
                watchMobileDownloadJobV2Visual(job, slot);

                handler.post(() -> {

                    slot.button.setText(
                            "⬇ Descargando..."
                    );

                    slot.status.setText(
                            "🕐 Preparando canción para el móvil..."
                    );

                    // El seguimiento, la transferencia y la publicación
                    // pertenecen al servicio; nunca ejecutar el gestor V1.
                    slot.status.setText(
                            "Preparando descarga en segundo plano…"
                    );
                });

            } catch (Exception e) {

                ;

                handler.post(() -> {

                    slot.button.setEnabled(true);

                    slot.button.setText(
                            "📱 Offline"
                    );

                    slot.status.setText(
                            "❌ " + e.getMessage()
                    );
                });
            }
        });
    }

