    private void downloadAlbumOffline(
            List<DownloadSlot> slots) {

        if (slots == null || slots.isEmpty()) {

            Toast.makeText(
                    this,
                    "⚠️ Este álbum no tiene canciones",
                    Toast.LENGTH_SHORT
            ).show();

            return;
        }

        if (offlineFolderUri == null) {

            Toast.makeText(
                    this,
                    "📂 Selecciona primero la carpeta offline",
                    Toast.LENGTH_LONG
            ).show();

            chooseOfflineFolder();
            return;
        }

        Toast.makeText(
                this,
                "📱 Guardando " + slots.size()
                        + " canciones offline...",
                Toast.LENGTH_LONG
        ).show();

        final String albumGroup =
                java.util.UUID.randomUUID().toString();

        String detectedAlbumTitle = "Álbum";

        if (
                slots.get(0).albumTrack != null &&
                slots.get(0).albumTrack.album != null &&
                !slots.get(0).albumTrack.album.isEmpty()
        ) {
            detectedAlbumTitle =
                    slots.get(0).albumTrack.album;
        }

        final String albumTitle =
                detectedAlbumTitle;

        final int albumTrackTotal =
                slots.size();

        executor.execute(() -> {

            for (int i = 0; i < slots.size(); i++) {

                DownloadSlot slot =
                        slots.get(i);

                final int albumTrackIndex =
                        i + 1;

                handler.post(() -> {

                    slot.button.setEnabled(false);

                    slot.button.setText(
                            "⏳ Preparando..."
                    );

                    slot.status.setText(
                            "📱 Preparando descarga offline..."
                    );

                    slot.progress.setProgress(0);
                });

                try {

                    ApiClient.Song track =
                            slot.albumTrack;

                    startMobileDownloadAlbumTrack(
                            track,
                            slot,
                            albumGroup,
                            albumTitle,
                            albumTrackIndex,
                            albumTrackTotal
                    );

                    Thread.sleep(300);

                } catch (Exception e) {

                    handler.post(() -> {

                        slot.button.setEnabled(true);

                        slot.button.setText(
                                "📱 Offline"
                        );

                        slot.status.setText(
                                "❌ " + e.getMessage()
                        );
                    });
                }
            }
        });
    }

    private void downloadAlbum(
            ApiClient.Album album,
            List<DownloadSlot> slots) {

        Toast.makeText(
                this,
                "Preparando descarga del álbum...",
                Toast.LENGTH_LONG
        ).show();

        if (album == null || slots == null || slots.isEmpty()) {
            return;
        }

        final String albumGroup =
                java.util.UUID.randomUUID().toString();

        final String albumTitle =
                album.title == null ||
                album.title.isEmpty()
                        ? "Álbum"
                        : album.title;

        final int albumTrackTotal =
                slots.size();

        executor.execute(() -> {

            for (int i = 0; i < slots.size(); i++) {

                final DownloadSlot slot =
                        slots.get(i);

                final int albumTrackIndex =
                        i + 1;

                handler.post(() -> {

                    slot.button.setEnabled(false);

                    slot.button.setText(
                            "⏳ Buscando..."
                    );

                    slot.status.setText(
                            "🔎 Buscando audio..."
                    );

                    slot.progress.setProgress(0);
                });

                try {

                    ApiClient.Song resolved =
                            api().resolveAlbumTrack(
                                    slot.albumTrack.artist,
                                    slot.albumTrack.title
                            );

                    String videoId =
                            resolved.id;

                    if (
                            videoId == null ||
                            videoId.isEmpty()
                    ) {

                        throw new Exception(
                                "No se encontró el audio."
                        );
                    }

                    JSONObject result =
                            api().download(
                                    videoId,
                                    slot.title,
                                    albumGroup,
                                    albumTitle,
                                    albumTrackIndex,
                                    albumTrackTotal
                            );

                    String job =
                            result.optString(
                                    "job",
                                    ""
                            );

                    if (job.isEmpty()) {

                        throw new Exception(
                                "El servidor no devolvió el trabajo."
                        );
                    }

                    handler.post(() -> {

                        slot.button.setText(
                                "⬇ Descargando..."
                        );

                        slot.status.setText(
                                "🕐 Procesando cola..."
                        );

                        watchDownloadJob(
                                job,
                                slot
                        );
                    });

                    Thread.sleep(300);

                } catch (Exception e) {

                    handler.post(() -> {

                        slot.status.setText(
                                "❌ " + e.getMessage()
                        );

                        slot.button.setText(
                                "↻ Reintentar"
                        );

                        slot.button.setEnabled(true);
                    });
                }
            }
        });
    }

